INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('jupiter-fi', 'Xe Jupiter Fi', 'yamaha', '[\"xe-so\"]', 33500000, 33500000, '/sites/hungphat/img/2024/11/xe-jupiter-fi-mau-xam.webp', '[\"/sites/hungphat/img/2024/11/xe-jupiter-fi-mau-xam.webp\"]', '[\"Bạc\",\"Đen\",\"Đỏ\",\"Xám đậm\"]', '[{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Bạc\"}],\"img\":\"/sites/hungphat/img/2024/11/xe-jupiter-fi-mau-trang.webp\",\"price\":33500000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/xe-jupiter-fi-mau-den.webp\",\"price\":33500000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Đỏ\"}],\"img\":\"/sites/hungphat/img/2024/11/xe-jupiter-fi-mau-do.webp\",\"price\":33500000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xám đậm\"}],\"img\":\"/sites/hungphat/img/2024/11/xe-jupiter-fi-mau-xam.webp\",\"price\":33500000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Loại\",\"value\":\"4 kỳ, 2 van, SOHC, làm mát bằng không khí tự nhiên\"},{\"label\":\"Bố trí xi lanh\",\"value\":\"Xy lanh đơn\"},{\"label\":\"Dung tích xy lanh (CC)\",\"value\":\"113.7\"},{\"label\":\"Đường kính và hành trình piston\",\"value\":\"50,0mm x 57,9mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"9,3:1\"},{\"label\":\"Công suất tối đa\",\"value\":\"Công suất tối đa\"},{\"label\":\"Mô men xoắn cực đại\",\"value\":\"9,9 N.m (0,99kgf.m) / 6.500 vòng/phút\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện / Cần khởi động\"},{\"label\":\"Hệ thống bôi trơn\",\"value\":\"Các-te ướt\"},{\"label\":\"Dung tích dầu máy\",\"value\":\"1,0 lít\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"4,1 lít\"},{\"label\":\"Mức tiêu thụ nhiên liệu (l/100km)\",\"value\":\"1,643\"},{\"label\":\"Hệ thống đánh lửa\",\"value\":\"T.C.I (kỹ thuật số)\"},{\"label\":\"Tỷ số truyền sơ cấp và thứ cấp\",\"value\":\"2,900 (58/20) / 3,154 (41/13)\"},{\"label\":\"Hệ thống ly hợp\",\"value\":\"Đa đĩa, ly tâm loại ướt\"},{\"label\":\"Tỷ số truyền động\",\"value\":\"1: 2,833 2: 1,875 3: 1,353 4: 1,045\"},{\"label\":\"Kiểu hệ thống truyền lực\",\"value\":\"4 số tròn\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Loại khung\",\"value\":\"Ống thép - Cấu trúc kim cương\"},{\"label\":\"Hệ thống giảm xóc trước\",\"value\":\"Kiểu ống lồng\"},{\"label\":\"Hành trình phuộc trước\",\"value\":\"100 mm\"},{\"label\":\"Độ lệch phương trục lái\",\"value\":\"26,5°/76mm\"},{\"label\":\"Hệ thống giảm xóc sau\",\"value\":\"Giảm chấn thủy lực lò xo trụ\"},{\"label\":\"Hành trình giảm xóc sau\",\"value\":\"70 mm\"},{\"label\":\"Phanh trước\",\"value\":\"Đĩa thủy lực\"},{\"label\":\"Phanh sau\",\"value\":\"Phanh cơ (đùm)\"},{\"label\":\"Lốp trước\",\"value\":\"70/90 - 17 38P (Lốp có săm)\"},{\"label\":\"Lốp sau\",\"value\":\"80/90 - 17 50P (Lốp có săm)\"},{\"label\":\"Đèn trước\",\"value\":\"Halogen 12V 35W / 35W x 1\"},{\"label\":\"Đèn trước/đèn sau\",\"value\":\"12V, 5W/21W x 1\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Kích thước (dài x rộng x cao)\",\"value\":\"1.935mm x 680mm x 1.065mm\"},{\"label\":\"Độ cao yên xe\",\"value\":\"765mm\"},{\"label\":\"765mm\",\"value\":\"125mm\"},{\"label\":\"Khoảng cách giữa 2 trục bánh xe\",\"value\":\"1.240mm\"},{\"label\":\"Trọng lượng ướt\",\"value\":\"103kg\"},{\"label\":\"Ngăn chứa đồ\",\"value\":\"7\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm / 30,000km (Tùy điều kiện nào đến trước)\"}]}]', '<p>Xe jupiter fi đã chính thức trình làng bộ sưu tập màu sắc mới, mang đến cho người tiêu dùng nhiều lựa chọn phong phú và đa dạng. Bên cạnh đó với giá xe jupiter fi cực ưu đãi, dòng xe này chính là lựa chọn lý tưởng cho nhiều người.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>XE JUPITER FI GIÁ RẺ ƯU ĐÃI CỦA YAMAHA</h2>\n<p>Trong phân khúc xe số với tầm giá 31 triệu đồng, <b>xe jupiter fi</b> đang thu hút sự chú ý mạnh mẽ từ người tiêu dùng Việt Nam. Điểm nổi bật nhất của <b>yamaha jupiter fi </b>là khả năng tiết kiệm nhiên liệu vượt trội mà vẫn đảm bảo hiệu suất vận hành mạnh mẽ. Bên cạnh đó với <b>giá xe jupiter fi</b> cực ưu đãi, dòng xe này chính là lựa chọn lý tưởng cho những ai tìm kiếm một chiếc xe vừa kinh tế vừa hiệu quả.</p>\n\n<h2>1. Giới thiệu về các phiên bản màu sắc của xe Jupiter Fi&nbsp;</h2>\n<p><b>Xe jupiter fi</b> đã chính thức trình làng bộ sưu tập màu sắc mới, mang đến cho người tiêu dùng nhiều lựa chọn phong phú và đa dạng. Các phiên bản màu sắc của dòng <b>xe máy</b> này không chỉ đơn thuần là những gam màu nổi bật mà còn thể hiện sự tinh tế và thanh lịch, với các tùy chọn như đen, xám, bạc và đỏ. Những màu sắc này không chỉ phù hợp với nhiều đối tượng khách hàng mà còn thể hiện phong cách sống hiện đại.</p>\n<p><em>Phiên bản màu đen sang trọng và quyền lực</em></p>\n<p>Phiên bản màu đen của <b>yamaha jupiter fi</b> toát lên vẻ đẹp mạnh mẽ và sang trọng. Màu đen luôn là lựa chọn hàng đầu cho những ai yêu thích sự lịch lãm và quyền lực. Với khả năng phối hợp dễ dàng với nhiều trang phục và phụ kiện khác nhau, chiếc xe này giúp người sử dụng tự tin hơn trong mọi hoàn cảnh.</p>\n<figure><img src=\"/sites/hungphat/img/2024/11/xe-jupiter-fi-mau-den.webp\" alt=\"\" loading=\"lazy\" width=\"1040\" height=\"800\"><figcaption><em>Xe Jupiter Fi phiên bản màu đen</em></figcaption></figure>\n<p><em>Phiên bản màu xám thanh lịch và hiện đại</em></p>\n<p>Màu xám được xem là một trong những gam màu trung tính được ưa chuộng nhất nhờ vào sự thanh lịch và hiện đại của nó. Phiên bản màu xám của <b>xe jupiter fi</b> không chỉ mang lại cảm giác nhẹ nhàng mà còn rất thời thượng. Đây là lựa chọn lý tưởng cho những ai muốn thể hiện phong cách cá nhân một cách tinh tế mà không cần phải phô trương.</p>\n<figure><img src=\"/sites/hungphat/img/2024/11/xe-jupiter-fi-mau-xam.webp\" alt=\"\" loading=\"lazy\" width=\"1040\" height=\"800\"><figcaption><em>Xe Jupiter Fi phiên bản màu xám</em></figcaption></figure>\n<p><em>Phiên bản màu bạc tinh tế và sắc xảo</em></p>\n<p>Với phiên bản màu bạc, <b>yamaha jupiter fi</b> mang đến vẻ đẹp sáng bóng và tinh tế. Màu bạc gợi lên hình ảnh của sự hiện đại và công nghệ cao, rất phù hợp với những người yêu thích sự mới mẻ và tiên tiến. Hơn nữa, đây cũng là gam màu dễ bảo quản, ít bám bẩn và giữ được vẻ đẹp lâu dài theo thời gian.</p>\n<figure><img src=\"/sites/hungphat/img/2024/11/xe-jupiter-fi-mau-trang.webp\" alt=\"\" loading=\"lazy\" width=\"1040\" height=\"800\"><figcaption><em>Xe Jupiter Fi phiên bản màu bạc</em></figcaption></figure>\n<p><em>Phiên bản màu đỏ năng động và nhiệt huyết</em></p>\n<p>Màu đỏ luôn tượng trưng cho sự nhiệt huyết và năng động. Phiên bản màu đỏ của <b>yamaha jupiter fi</b> chắc chắn sẽ thu hút ánh nhìn từ mọi người xung quanh. Đây là lựa chọn hoàn hảo cho những ai muốn thể hiện cá tính mạnh mẽ và đầy sức sống.</p>\n<figure><img src=\"/sites/hungphat/img/2024/11/xe-jupiter-fi-mau-do.webp\" alt=\"\" loading=\"lazy\" width=\"1040\" height=\"800\"><figcaption><em>Xe Jupiter Fi phiên bản màu đỏ</em></figcaption></figure>\n<p>Với bộ sưu tập màu sắc đa dạng này, <b>jupiter fi</b> đáp ứng nhu cầu của nhiều đối tượng khách hàng khác nhau, từ sinh viên trẻ trung năng động đến nhân viên văn phòng cần một phương tiện di chuyển tiện lợi hay các gia đình mong muốn sở hữu một chiếc xe bền bỉ. Chắc chắn rằng mỗi phiên bản đều mang đến trải nghiệm lái xe tuyệt vời cùng phong cách riêng biệt cho từng cá nhân. Hiện tại<b> giá xe jupiter fi</b> đang được bán chỉ từ 31 triệu đồng</p>\n<h2>2. Động cơ xe và tiện ích hiện đại của yamaha jupiter fi</h2>\n<p><em>Tiện ích hiện đại của xe jupiter fi</em></p>\n<p><b>Xe jupiter fi</b> không chỉ nổi bật với thiết kế tinh tế mà còn được trang bị nhiều tiện ích và công nghệ tiên tiến, mang lại trải nghiệm lái xe tối ưu cho người dùng. Dù vẫn sử dụng đồng hồ xe analog truyền thống, phiên bản này đã được nâng cấp với dãy đèn nền LED hiện đại, giúp tăng cường khả năng quan sát vào ban đêm. Đồng hồ xe hiển thị rõ ràng các thông số vận hành của xe, bao gồm công tơ mét, đèn cảnh báo mức nhiên liệu và chức năng báo lỗi tự động, hỗ trợ người lái trong việc theo dõi tình trạng xe một cách dễ dàng.</p>\n<p>Thiết kế yên xe của<b> jupiter fi </b>cũng được chăm chút kỹ lưỡng với hoa văn tròn nhỏ, không chỉ tạo cảm giác thoải mái mà còn tăng độ bám và chống trượt khi ngồi. Dưới yên là cốp xe có dung tích hợp lý, đủ để chứa một số vật dụng cá nhân cùng một mũ bảo hiểm nửa đầu.</p>\n\n<p>Xe vẫn duy trì sử dụng chìa khóa cơ tích hợp chức năng mở yên tiện lợi. Hệ thống khóa chống cạy giúp tăng cường độ an toàn cho phương tiện. Với mức giá hợp lý hiện tại, việc sở hữu <b>yamaha jupiter fi</b> mang đến những tiện nghi và công nghệ đáng giá, đáp ứng tốt nhu cầu của người tiêu dùng.</p>\n<p><em>Động cơ yamaha jupiter fi</em></p>\n<p><b>Xe jupiter fi</b> được trang bị khối động cơ mạnh mẽ với dung tích 115cc, 4 kỳ, 2 van SOHC và làm mát bằng không khí. Động cơ này cho phép xe đạt công suất tối đa lên đến 9,9 mã lực tại 7.000 vòng/phút và mô-men xoắn cực đại đạt 9,9 Nm tại 6.500 vòng/phút.</p>\n<p>Hệ thống phun xăng điện tử của<b> jupiter fi</b> không chỉ giúp cải thiện hiệu suất động cơ lên đến 20%, mà còn tiết kiệm nhiên liệu tới 20%. Với mức tiêu thụ khoảng chỉ 1,64 lít xăng cho mỗi quãng đường dài 100km, đây thực sự là lựa chọn lý tưởng cho những ai quan tâm đến kinh tế và bảo vệ môi trường.</p>\n\n<p>Trải nghiệm thực tế cho thấy rằng việc sở hữu <b>xe jupiter fi</b> mang lại cảm giác lái vô cùng mượt mà và ổn định trong suốt quá trình chuyển số từ thấp đến cao. Điều này không chỉ nâng cao trải nghiệm lái xe mà còn đảm bảo sự an toàn và thoải mái cho người sử dụng.</p>\n<p>Với những cải tiến vượt bậc về động cơ và hiệu suất hoạt động, <b>xe jupiter fi </b>chắc chắn sẽ là một trong những lựa chọn hàng đầu trong phân khúc xe số cao cấp hiện nay.</p>\n<h2>3. Giá xe jupiter fi tại Xe máy Hùng Phát&nbsp;</h2>\n<p>Hệ thống xe máy Hùng Phát tự hào là một trong những cửa hàng xe máy hàng đầu và uy tín nhất trên thị trường hiện nay. Với nhiều năm kinh nghiệm trong ngành, chúng tôi cam kết mang đến cho khách hàng những sản phẩm chất lượng cao cùng dịch vụ tận tâm nhất.</p>\n<p>Tại Hùng Phát, chúng tôi cung cấp đầy đủ các phiên bản và dòng xe từ những thương hiệu nổi tiếng như Honda, Yamaha, Suzuki, SYM, xe điện Yadea và các mẫu xe nhập khẩu. Nếu bạn đang tìm kiếm một địa chỉ để tham khảo <a href=\"/xe-may?nhom=yamaha\"><b>giá xe yamaha</b></a> chính hãng, hãy đến ngay với chúng tôi!</p>\n\n<p>Để biết thêm thông tin chi tiết về<b> giá xe jupter fi</b> cũng như các chương trình khuyến mãi dành cho dòng xe số Yamaha, quý khách vui lòng liên hệ qua hotline. Đội ngũ tư vấn viên của chúng tôi luôn sẵn sàng hỗ trợ bạn một cách nhanh chóng và miễn phí. Hãy để Hùng Phát đồng hành cùng bạn trên mọi nẻo đường!</p>\n<p><strong>HỆ THỐNG XE MÁY HÙNG PHÁT&nbsp;</strong></p>', 1);
