INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-air-blade-160', 'Xe Air blade 160', 'honda', '[]', 56800000, 59300000, '/sites/hungphat/img/2024/11/airblade-160-phien-ban-the-thao-mau-xam-do-den.webp', '[\"/sites/hungphat/img/2024/11/airblade-160-phien-ban-the-thao-mau-xam-do-den.webp\"]', '[\"Bạc Xanh Đen\",\"Đen Bạc\",\"Xám Đỏ Đen\",\"Xanh Đen Vàng\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Bạc\"}],\"img\":\"/sites/hungphat/img/2024/11/airblade-160-phien-ban-tieu-chuan-mau-den-bac.webp\",\"price\":56800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Bạc Xanh Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/airblade-160-phien-ban-cao-cap-mau-bac-xanh-den.webp\",\"price\":57800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh Đen Vàng\"}],\"img\":\"/sites/hungphat/img/2024/11/airblade-160-phien-ban-dac-biet-mau-xanh-den-vang.webp\",\"price\":58300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao\"},{\"name\":\"Màu sắc\",\"value\":\"Xám Đỏ Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/airblade-160-phien-ban-the-thao-mau-xam-do-den.webp\",\"price\":59300000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Loại động cơ\",\"value\":\"Xăng, 4 kỳ, 1 xi-lanh, làm mát bằng chất lỏng\"},{\"label\":\"Công suất tối đa\",\"value\":\"11,2kW/8000 vòng/phút\"},{\"label\":\"Dung tích nhớt máy\",\"value\":\"0,8 lít khi thay nhớt 0,9 lít khi rã máy\"},{\"label\":\"Mức tiêu thụ nhiên liệu\",\"value\":\"2,19l/100km\"},{\"label\":\"Loại truyền động\",\"value\":\"Dây đai, biến thiên vô cấp\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Moment cực đại\",\"value\":\"14,6 N.m/6500 vòng/phút\"},{\"label\":\"Dung tích xy-lanh\",\"value\":\"156,9cm3\"},{\"label\":\"Đường kính x Hành trình pít tông\",\"value\":\"60,00mm x 55,50mm\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"4,4 lít\"},{\"label\":\"Tỷ số nén\",\"value\":\"12:1\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Kích cỡ lốp trước/ sau\",\"value\":\"Lốp trước 90/80 - Lốp sau 100/80\"},{\"label\":\"Phuộc trước\",\"value\":\"Ống lồng, giảm chấn thủy lực\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ, giảm chấn thủy lực\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Khối lượng bản thân\",\"value\":\"114kg\"},{\"label\":\"Dài x Rộng x Cao\",\"value\":\"1.890mm x 686mm x 1.116mm\"},{\"label\":\"Khoảng cách trục bánh xe\",\"value\":\"1.286mm\"},{\"label\":\"Độ cao yên\",\"value\":\"775mm\"},{\"label\":\"Khoảng sáng gầm xe\",\"value\":\"142mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000km (tùy điều kiện nào đến trước)\"}]}]', '<p>Kết hợp hoàn hảo giữa công nghệ tiên tiến và hiệu suất vượt trội, honda air blade 160 hứa hẹn mang đến cho người lái những trải nghiệm tuyệt vời nhất trên mọi cung đường.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE AIR BLADE 160 CỦA HONDA MỚI NHẤT HÔM NAY&nbsp;</h2>\n<p>Kết hợp hoàn hảo giữa công nghệ tiên tiến và hiệu suất vượt trội, <b>air blade 160 </b>hứa hẹn mang đến cho người lái những trải nghiệm tuyệt vời nhất trên mọi cung đường. <b>Honda air blade 160</b> nổi bật với những đường nét sắc sảo, tạo nên vẻ ngoài mạnh mẽ nhưng vẫn rất thanh lịch. Hãy cùng Hùng Phát khám phá những ưu điểm nổi bật của <b>xe ab 160</b> và cập nhật <b>giá xe airblade 160 </b>mới nhất để không bỏ lỡ cơ hội sở hữu mẫu xe ga đẳng cấp này!</p>\n\n<h2>1. Khám phá sự đẳng cấp trong thiết kế của xe air blade 160</h2>\n<p><em>Thiết kế thể thao đẳng cấp và sang trọng</em></p>\n<p><b>Honda air blade 160</b> không chỉ đơn thuần là một phương tiện di chuyển, mà còn là biểu tượng của sự tinh tế trong thiết kế. Lấy cảm hứng từ hình ảnh “tia sét”, mẫu xe này sở hữu vẻ ngoài mạnh mẽ, hiện đại với những đường nét sắc sảo và gọn gàng. Tem số 160 mới được thiết kế nổi bật, mang đến cảm giác hiện đại và năng động cho người lái.</p>\n\n<p><em>Đa dạng phiên bản và màu sắc phù hợp mọi gu thẩm mỹ</em></p>\n<p><b>Air blade 160</b> tự hào mang đến một bộ sưu tập phiên bản đa dạng, phù hợp với sở thích và nhu cầu của từng khách hàng. Phiên bản Tiêu chuẩn với gam màu tối mạnh mẽ, kết hợp tinh tế cùng các chi tiết màu xám, không chỉ tạo nên vẻ đẹp thanh lịch mà còn thể hiện phong cách thể thao đầy cuốn hút.</p>\n<p>Với những ai yêu thích sự sang trọng, phiên bản Cao cấp của <b>xe ab 160</b> với tông màu Bạc Xanh Đen cùng các chi tiết phối màu thời thượng sẽ là lựa chọn lý tưởng. Mỗi chi tiết trên xe đều được chăm chút kỹ lưỡng, khẳng định phong cách cao cấp và mạnh mẽ.</p>\n<p>Phiên bản Đặc biệt gây ấn tượng mạnh mẽ với tông màu chủ đạo Xanh Đen Vàng độc đáo cùng thiết kế sắc nét. Sự kết hợp này không chỉ thể hiện cá tính nổi bật mà còn thu hút mọi ánh nhìn ngay từ lần đầu tiên.</p>\n<p>Cuối cùng, phiên bản Thể Thao của <b>honda air blade 160</b> mang đến một diện mạo khỏe khoắn với tông màu xám mạnh mẽ, được điểm xuyết bởi các miếng ốp đỏ trên thân xe tạo nên sự nổi bật đầy ấn tượng. Yên xe màu xám đen cùng dải chỉ đỏ càng làm tăng thêm vẻ nam tính và sức hút cho mẫu xe này.</p>\n<p><em>Cụm đèn LED hiện đại tạo nên sự khác biệt</em></p>\n<p><b>Ab 160 </b>được trang bị cụm đèn LED định vị cỡ lớn, mang lại ánh sáng mạnh mẽ và rõ nét. Thiết kế đèn trước mô phỏng cấu trúc của những mẫu xe phân khối lớn, góp phần tạo nên vẻ thể thao năng động cho chiếc xe.</p>\n<p><b>Air blade 160</b> không chỉ là một chiếc xe máy mà còn sự kết hợp hoàn hảo giữa kiểu dáng thể thao và tính năng hiện đại, <b>xe ab 160 </b>chắc chắn sẽ chinh phục mọi tín đồ yêu thích sự khác biệt và đẳng cấp.</p>\n<h2>2. Động cơ eSP+ 4 van mạnh mẽ của xe AB 160</h2>\n<p><b>Honda air blade 160 </b>nổi bật với hệ thống động cơ eSP+ 4 van, mang đến cho người dùng trải nghiệm lái xe vượt trội. Động cơ này không chỉ gia tăng công suất mà còn đảm bảo vận hành êm ái, giúp người lái cảm nhận sự thoải mái trong từng chuyến đi.</p>\n\n<p>Với thiết kế thông minh, động cơ eSP+ tối ưu hóa quá trình đốt cháy nhiên liệu, từ đó giảm thiểu mức tiêu thụ và tiết kiệm chi phí cho người sử dụng. Bên cạnh đó, công nghệ này góp phần giảm thiểu khí thải độc hại ra môi trường, thể hiện cam kết của hãng đối với việc bảo vệ thiên nhiên.</p>\n<p>Khả năng vận hành mạnh mẽ của động cơ eSP+ 4 van không chỉ mang lại sự linh hoạt trong di chuyển mà còn giúp xe duy trì ổn định ở tốc độ cao. Điều này khiến <b>xe ab 160</b> trở thành lựa chọn lý tưởng cho những ai yêu thích sự năng động và hiệu suất cao trong mỗi chuyến đi. Với<b> xe air blade 160</b>, bạn không chỉ sở hữu một chiếc xe máy mà còn là một phần của xu hướng sống xanh và bền vững.</p>\n<h2>3. Tính năng và tiện ích hiện đại của Honda Air blade 160</h2>\n<p><b>Air blade 160</b> là biểu tượng của sự kết hợp hoàn hảo giữa thiết kế tinh tế và công nghệ tiên tiến. Dưới đây là những tính năng nổi bật và tiện ích hiện đại mà mẫu xe này mang lại cho người sử dụng.</p>\n<p><em>Đèn chiếu sáng phía trước luôn bật</em></p>\n<p><b>Ab160</b> được trang bị chế độ đèn chi sáng luôn bật, đảm bảo người lái có tầm nhìn tối ưu trong mọi điều kiện ánh sáng. Tính năng này không chỉ giúp người sử dụng dễ dàng quan sát mà còn nâng cao khả năng nhận diện của xe trên đường, từ đó giảm thiểu nguy cơ va chạm với các phương tiện khác.</p>\n\n<p><em>Hệ thống chống bó cứng phanh ABS an toàn</em></p>\n<p>Với hệ thống chống bó cứng phanh ABS cho bánh trước, <b>honda air blade 160</b> mang lại sự ổn định và an toàn tối đa trong những tình huống khẩn cấp hoặc khi di chuyển trên đường trơn trượt. Điều này giúp người lái yên tâm hơn khi điều khiển xe, đặc biệt là trong những điều kiện thời tiết không thuận lợi.</p>\n<p><em>Mặt đồng hồ LCD thể thao hiện đại</em></p>\n<p>Mặt đồng hồ LCD kỹ thuật số với thiết kế tinh tế và hiện đại không chỉ tăng cường khả năng hiển thị mà còn giúp người dùng dễ dàng theo dõi thông tin. Ngoài việc hiển thị hành trình, đồng hồ <b>xe ab 160</b> còn cung cấp thông tin về mức tiêu thụ nhiên liệu tức thời và trung bình, giúp người lái nắm bắt tình hình sử dụng nhiên liệu trong từng hoàn cảnh cụ thể.</p>\n<p><em>Hệ thống khóa thông minh Smart Key</em></p>\n<p>Với hệ thống khóa thông minh SMART Key, việc khóa/mở xe trở nên đơn giản hơn bao giờ hết. Người dùng có thể xác định vị trí xe và kích hoạt chức năng báo động chỉ bằng một nút bấm trên thiết bị FOB, mang lại sự tiện lợi và an tâm tối đa cho khách hàng.</p>\n\n<p><em>Cổng sạc USB tiện lợi</em></p>\n<p><b>Air blade 160 </b>được trang bị cổng sạc USB (Loại A) với nắp chống nước nằm trong hộc đựng đồ dưới yên xe. Với dòng điện đầu ra lên tới 2,1A, việc sạc điện thoại trở nên nhanh chóng và thuận tiện hơn bao giờ hết, nâng cao trải nghiệm của khách hàng trên mọi hành trình.</p>\n\n<p><em>Hộc đựng đồ dung tích lớn</em></p>\n<p>Hộc đựng đồ rộng rãi với dung tích lên tới 23,2 lít cho phép chứa đến hai mũ bảo hiểm nửa đầu cùng nhiều vật dụng cá nhân khác mà vẫn giữ nguyên thiết kế gọn gàng. Đặc biệt, đèn soi hộc đồ giúp người dùng dễ dàng tìm kiếm vật dụng trong điều kiện thiếu sáng. Vách ngăn thông minh cũng cho phép chia nhỏ không gian lưu trữ thành hai khoang riêng biệt, tăng tính tiện lợi cho người sử dụng.</p>\n\n<p>Với những tính năng vượt trội cùng tiện ích hiện đại, <b>honda air blade 160</b> xứng đáng là lựa chọn hàng đầu cho những ai yêu thích sự năng động và phong cách sống hiện đại.&nbsp;</p>\n<h2>3. Giá xe AirBlade 160 chính hãng tại Hệ thống xe máy Hùng Phát</h2>\n<p>Hiện nay, dòng <b>xe ab 160</b> đã có mặt tại nhiều cửa hàng Honda trên toàn quốc. Tuy nhiên, để đảm bảo quý khách hàng nhận được sản phẩm chất lượng với <b>giá xe airblade 160</b> hợp lý, việc lựa chọn những cửa hàng lớn và uy tín là điều vô cùng quan trọng.</p>\n<p><b>Giá xe air blade 160</b> phiên bản tiêu chuẩn: 56.800.000đ</p>\n<p><b>Giá xe airblade 160</b> phiên bản cao cấp: 57.800.000đ</p>\n<p><b>Giá xe air blade 160 </b>phiên bản đặc biệt: 58.300.000đ</p>\n<p><b>Giá xe airblade 160 </b>phiên bản thể thao: 59.300.000đ</p>\n<p>Hệ thống xe máy Hùng Phát tự hào là đại lý phân phối chính hãng của các thương hiệu nổi tiếng như Honda, Yamaha, SYM và Suzuki. Chúng tôi cam kết mang đến cho khách hàng những sản phẩm chất lượng cao với mức <a href=\"/xe-may?nhom=honda\"><b>giá xe honda</b></a> cực kỳ ưu đãi cho mẫu xe <b>honda air blade 160</b>.</p>\n\n<p>Nếu quý khách đang tìm kiếm thông tin về <b>giá xe air blade 160</b> hoặc các dòng <a href=\"/xe-may\"><b>xe máy</b></a> khác, hãy liên hệ ngay với chúng tôi qua hotline. Đội ngũ nhân viên chuyên nghiệp và tận tâm của Hùng Phát luôn sẵn sàng tư vấn chi tiết và hỗ trợ quý khách một cách tốt nhất.</p>\n<p>Hệ thống xe máy Hùng Phát cam kết mang lại sự hài lòng tối đa cho quý khách hàng trong mỗi lần trải nghiệm dịch vụ của chúng tôi. Chúng tôi rất mong được phục vụ bạn!</p>\n<p><strong>HỆ THỐNG XE MÁY HÙNG PHÁT&nbsp;</strong></p>', 1);
