INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-blade', 'Xe Blade', 'honda', '[\"xe-so\"]', 20200000, 23400000, '/sites/hungphat/img/2024/11/blade-phien-ban-the-thao-mau-den-do.webp', '[\"/sites/hungphat/img/2024/11/blade-phien-ban-the-thao-mau-den-do.webp\"]', '[\"Đen\",\"Đen Đỏ\",\"Đen Xanh đậm\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Đỏ\"}],\"img\":\"/sites/hungphat/img/2024/11/blade-phien-ban-tieu-chuan-mau-den-do.webp\",\"price\":20200000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Xanh đậm\"}],\"img\":\"/sites/hungphat/img/2024/11/blade-phien-ban-tieu-chuan-mau-den-xanh.webp\",\"price\":20200000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/blade-phien-ban-dac-biet-mau-den.webp\",\"price\":21800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao\"},{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/blade-phien-ban-the-thao-mau-den.webp\",\"price\":23400000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Đỏ\"}],\"img\":\"/sites/hungphat/img/2024/11/blade-phien-ban-the-thao-mau-den-do.webp\",\"price\":23400000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Xanh đậm\"}],\"img\":\"/sites/hungphat/img/2024/11/balde-phien-ban-the-thao-mau-den-xanh.webp\",\"price\":23400000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Dung tích bình xăng\",\"value\":\"3,7 L\"},{\"label\":\"Công suất tối đa\",\"value\":\"6,18 kW/7.500 vòng/phút\"},{\"label\":\"Loại động cơ\",\"value\":\"Xăng, 4 kỳ, 1 xilanh, làm mát bằng không khí\"},{\"label\":\"Dung tích nhớt máy\",\"value\":\"0,8 lít khi thay nhớt 1,0 lít khi rã máy\"},{\"label\":\"Mức tiêu thụ nhiên liệu\",\"value\":\"1,85l/100 km\"},{\"label\":\"Hộp số\",\"value\":\"Cơ khí, 4 số tròn\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Đạp chân/Điện\"},{\"label\":\"Moment cực đại\",\"value\":\"8,65 Nm/5.500 vòng/phút\"},{\"label\":\"Dung tích xy-lanh\",\"value\":\"109,1 cm3\"},{\"label\":\"Đường kính x Hành trình pít tông\",\"value\":\"50,0 x 55,6 mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"9,0 : 1\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Kích cỡ lốp trước/ sau\",\"value\":\"Trước: 70/90 -17 M/C 38P Sau: 80/90 - 17 M/C 50P\"},{\"label\":\"Phuộc trước\",\"value\":\"Ống lồng, giảm chấn thủy lực\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ, giảm chấn thủy lực\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Khối lượng bản thân\",\"value\":\"99 kg (vành đúc) 98 kg (vành nan hoa, phanh trước loại phanh cơ) 99 kg (vành nan hoa, phanh trước loại phanh đĩa)\"},{\"label\":\"Dài x Rộng x Cao\",\"value\":\"1.920 x 702 x 1.075 mm\"},{\"label\":\"Khoảng cách trục bánh xe\",\"value\":\"1.217 mm\"},{\"label\":\"Độ cao yên\",\"value\":\"769mm\"},{\"label\":\"Khoảng sáng gầm xe\",\"value\":\"141mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000km (tùy điều kiện nào đến trước)\"}]}]', '<p>Wave blade không chỉ đơn thuần là một phương tiện di chuyển, mà còn là biểu tượng của phong cách sống hiện đại, năng động và trẻ trung.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>CẬP NHẬT GIÁ XE BLADE 110 HONDA MỚI NHẤT HIỆN NAY</h2>\n<p><b>Xe blade 110</b> là một trong những mẫu xe số nổi bật của nhà Honda. Với thiết nhỏ gọn, đường nét tinh tế và cá tính, <b>wave blade</b> này không chỉ mang đến vẻ đẹp thanh lịch mà còn thể hiện phong cách thể thao của người sở hữu.</p>\n<p>Phiên bản mới nhất của <b>honda blade</b> tiếp tục khẳng định đẳng cấp với thiết kế năng động và những màu sắc đầy ấn tượng.4 Điều này giúp khách hàng tự tin thể hiện phong cách cá nhân một cách rõ nét. <b>Xe blade 110</b> không chỉ là phương tiện di chuyển mà còn là biểu tượng của sự trẻ trung, năng động và cá tính trong cuộc sống hiện đại. Dưới đây là bài giới thiệu về <b>xe blade </b>và <b>giá xe blade</b> mới nhất hiện nay tại Hùng Phát!</p>\n\n<h2>1. Giới thiệu về thiết kế của xe Blade 110</h2>\n<p><em>Thiết kế hiện đại và thể thao</em></p>\n<p><b>Wave blade</b> không chỉ đơn thuần là một phương tiện di chuyển, mà còn là biểu tượng của phong cách sống hiện đại, năng động và trẻ trung. Với phần ốp nhựa được thiết kế chắc chắn, vuốt gọn theo chiều dài thân xe giúp xe trở nên thanh thoát hơn. Phần đuôi xe được tạo hình trẻ trung, góp phần tôn lên vẻ đẹp thể thao của sản phẩm. Cụm đèn hậu liền khối không chỉ tạo nên sự đồng nhất trong thiết kế mà còn mang lại cảm giác chắc chắn, giúp người dùng yên tâm hơn khi di chuyển.</p>\n\n<p><em>Màu đa dạng và ấn tượng</em></p>\n<p>Một trong những điểm nổi bật khiến <b>blade 110</b> trở thành lựa chọn hàng đầu tại Việt Nam chính là sự đa dạng trong bảng màu sắc. Dòng xe này không chỉ thu hút bởi thiết kế thể thao mà còn bởi khả năng đáp ứng nhu cầu thẩm mỹ của nhiều đối tượng khách hàng khác nhau. Hiện tại, phiên bản thể thao của <b>honda blade</b> được cung cấp với ba màu sắc độc đáo, mỗi màu đều mang một cá tính riêng biệt, phù hợp với sở thích và phong cách sống của từng người.</p>\n<p><em>Tem xe tinh tế và độc đáo</em></p>\n<p>Không chỉ dừng lại ở thiết kế tổng thể, từng phiên bản của <b>xe blade</b> còn được trang bị tem xe với những họa tiết độc đáo, thể hiện rõ nét phong cách cá nhân:</p>\n<p>– Phiên bản Thể thao (vành đúc phanh đĩa): Được trang trí bằng tem “SPORT” mới mẻ với gam màu trẻ trung nổi bật. Thiết kế này không chỉ tạo cảm giác hiện đại mà còn mang đến sự năng động cho người sử dụng.</p>\n<p>– Phiên bản Đặc biệt (vành nan hoa, phanh đĩa): Với diện mạo sắc sảo cùng dải tem màu vàng thanh thoát chạy dọc thân xe, chữ “SPECIAL” nổi bật càng làm tăng thêm sự cuốn hút cho phiên bản này.</p>\n<p>– Phiên bản Tiêu chuẩn (vành nan hoa, phanh cơ): Tem xe được cách điệu một cách tinh tế với sự phối hợp hài hòa giữa các mảng màu trẻ trung và khỏe khoắn, tạo nên một tổng thể bắt mắt.</p>\n<p>Hiện nay, hệ thống xe máy Hùng Phát đang cung cấp đầy đủ các phiên bản và màu sắc của <b>honda blade</b> với <b>giá xe blade </b>cực ưu đãi. Quý khách hàng có nhu cầu sở hữu chiếc xe này có thể liên hệ qua hotline để nhận những ưu đãi hấp dẫn nhất!</p>\n<p><b>Blade 110</b> không chỉ đơn thuần là phương tiện di chuyển mà còn là biểu tượng cho phong cách sống hiện đại. Với thiết kế tinh tế cùng bảng màu đa dạng và tem xe độc đáo, chiếc xe này chắc chắn sẽ làm hài lòng cả những khách hàng khó tính nhất.</p>\n<h2>2. Giới thiệu về công nghệ và động cơ của xe Honda Blade&nbsp;</h2>\n<p><b>Honda blade</b> được trang bị động cơ 110cc. Với độ bền cao và khả năng vận hành ổn định, động cơ này không chỉ mang lại hiệu suất tối ưu mà còn tiết kiệm nhiên liệu vượt trội. Đặc biệt, <b>xe blade</b> đáp ứng tiêu chuẩn khí thải Euro 3 nghiêm ngặt, góp phần bảo vệ môi trường và giảm thiểu ô nhiễm.</p>\n\n<p>Một trong những điểm mạnh của <b>wave blade</b> chính là cảm giác lái xe êm ái. Thiết kế khí động học tinh tế cùng trọng lượng nhẹ giúp xe dễ dàng di chuyển trong mọi điều kiện giao thông. Vị trí ngồi lái được tính toán hợp lý, tạo ra sự thoải mái tối đa cho người điều khiển trong suốt hành trình dài.</p>\n<p>Với sự kết hợp hoàn hảo giữa công nghệ tiên tiến và thiết kế thông minh, <b>blade 110 </b>không chỉ là phương tiện di chuyển mà còn là người bạn đồng hành đáng tin cậy trên mọi nẻo đường. Sự lựa chọn hoàn hảo cho những ai yêu thích sự tiện nghi và an toàn khi tham gia giao thông.</p>\n<h2>3. Giới thiệu về tính năng của xe Wave Blade&nbsp;</h2>\n<p><em>Ổ khóa đa năng 3 trong 1</em></p>\n<p><b>Xe blade</b> được trang bị ổ khóa đa năng với thiết kế hiện đại, bao gồm khóa điện, khóa cổ và khóa từ. Tính năng này không chỉ nâng cao độ an toàn cho xe mà còn mang lại sự tiện lợi tối ưu cho người sử dụng. Hệ thống khóa chống rỉ sét hiệu quả, đảm bảo bền bỉ theo thời gian.</p>\n\n<p><em>Đèn chiếu sáng phía trước luôn hoạt động</em></p>\n<p>Một trong những điểm nổi bật của <b>wave blade</b> là hệ thống đèn chiếu sáng phía trước luôn được bật. Tính năng này giúp người lái có tầm nhìn rõ ràng nhất trong điều kiện ánh sáng yếu, đồng thời tăng khả năng nhận diện xe trên đường phố, góp phần nâng cao an toàn khi di chuyển.</p>\n\n<p><em>Mặt đồng hồ hiện đại và tinh tế</em></p>\n<p>Mặt đồng hồ của <b>xe blade</b> được thiết kế với đường nét tinh tế và hiện đại. Các thông số quan trọng được hiển thị rõ ràng, giúp người điều khiển dễ dàng theo dõi và kiểm soát tình trạng xe một cách thuận tiện nhất.</p>\n\n<p>Với những tính năng vượt trội này, <b>honda blade</b> không chỉ đáp ứng nhu cầu di chuyển hàng ngày mà còn mang đến trải nghiệm lái xe an toàn và thoải mái cho người sử dụng.</p>\n<h2>4. Cập nhật giá xe Blade tại Hùng Phát mới nhất hôm nay</h2>\n<p>Hệ thống xe máy Hùng Phát tự hào là một trong những địa chỉ hàng đầu trong lĩnh vực kinh doanh <a href=\"/xe-may\"><strong>xe máy</strong></a> chính hãng tại Việt Nam. Chúng tôi cam kết mang đến cho quý khách hàng những trải nghiệm mua sắm tuyệt vời nhất cùng dịch vụ hậu mãi chuyên nghiệp. Hiện tại,<b> blade 110</b> đang được bán tại đây với đầy đủ các phiên bản và mức giá xe Blade cực kỳ hấp dẫn.</p>\n<p><strong>Giá xe blade</strong> phiên bản tiêu chuẩn: 20.200.000đ</p>\n<p><strong>Giá xe blade</strong> phiên bản đặc biệt: 21.800.000đ</p>\n<p><strong>Giá xe blade</strong> phiên bản thể thao: 23.400.000đ</p>\n\n<p>Ưu đãi độc quyền khi mua xe tại Hùng Phát:</p>\n<p>– Tư vấn chuyên nghiệp 24/7: Đội ngũ nhân viên tận tâm và giàu kinh nghiệm của chúng tôi luôn sẵn sàng hỗ trợ quý khách mọi lúc, mọi nơi qua hotline, Zalo, fanpage hoặc trực tiếp tại các chi nhánh thuộc hệ thống.&nbsp;</p>\n<p>– Hỗ trợ mua xe trả góp: Đặc biệt, Hùng Phát cung cấp chương trình hỗ trợ mua xe trả góp với thủ tục đơn giản và lãi suất ưu đãi. Quý khách chỉ cần thanh toán trước từ 10% là có thể sở hữu ngay chiếc xe yêu thích.</p>\n<p>– Chương trình thu xe cũ đổi xe mới: Giúp quý khách dễ dàng nâng cấp lên đời xe mới thông qua chương trình thu hồi xe cũ đổi lấy xe mới tiện lợi và nhanh chóng.</p>\n<p>– Dịch vụ giao xe tận nơi: Nhằm tạo điều kiện thuận lợi nhất cho khách hàng, chúng tôi cung cấp dịch vụ giao xe tận nhà nhanh chóng và an toàn, giúp quý khách tiết kiệm thời gian.</p>\n<p>– Quà tặng độc quyền hấp dẫn: Khi mua <a href=\"/xe-may?nhom=honda\"><strong>xe máy honda</strong></a> tại Hùng Phát, quý khách sẽ nhận ngay combo quà tặng gồm 14 phần quà trị giá lên tới 2.350.000 đồng cùng nhiều chương trình khuyến mãi thú vị khác.</p>\n<p>Đừng bỏ lỡ cơ hội sở hữu ngay <b>giá xe blade</b> ưu đãi nhất hiện nay! Mọi chi tiết xin lòng liên hệ qua hotline để được tư vấn chi tiết.</p>\n<p><strong>HỆ THỐNG XE MÁY HÙNG PHÁT&nbsp;</strong></p>', 1);
