INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-cbr-150r', 'Xe CBR 150R', 'honda', '[\"xe-tay-con\"]', 70300000, 71800000, '/sites/hungphat/img/2024/11/cbr150r-phien-ban-the-thao-mau-do.webp', '[\"/sites/hungphat/img/2024/11/cbr150r-phien-ban-the-thao-mau-do.webp\"]', '[\"Đen nhám\",\"Đỏ\",\"Đỏ Đen\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/cbr150r-phien-ban-tieu-chuan-mau-do-den.webp\",\"price\":70300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Đen nhám\"}],\"img\":\"/sites/hungphat/img/2024/11/cbr150r-phien-ban-dac-biet-mau-den-nham.webp\",\"price\":70300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ\"}],\"img\":\"/sites/hungphat/img/2024/11/cbr150r-phien-ban-the-thao-mau-do.webp\",\"price\":71800000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Dung tích bình xăng\",\"value\":\"12 lít\"},{\"label\":\"Loại động cơ\",\"value\":\"4 kỳ, 1 xi lanh, làm mát bằng chất lỏng\"},{\"label\":\"Công suất tối đa\",\"value\":\"12,6kW/9.000 vòng/phút\"},{\"label\":\"Dung tích nhớt máy\",\"value\":\"Sau khi xả 1,1 lít Sau khi rã máy 1,3 lít\"},{\"label\":\"Mức tiêu thụ nhiên liệu\",\"value\":\"2,91l/100km**\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Moment cực đại\",\"value\":\"14,4Nm/7.000 vòng/phút\"},{\"label\":\"Dung tích xy-lanh\",\"value\":\"149,2 cm3\"},{\"label\":\"Đường kính x Hành trình pít tông\",\"value\":\"57,3 mm x 57,8 mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"11,3:1\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Kích cỡ lốp trước/ sau\",\"value\":\"Trước: 100/80-17M/C Sau: 130/70-17M/C\"},{\"label\":\"Phuộc trước\",\"value\":\"Ống lồng, giảm chấn thủy lực, hành trình ngược\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ đơn sử dụng liên kết Pro-Link\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Khối lượng bản thân\",\"value\":\"139kg\"},{\"label\":\"Dài x Rộng x Cao\",\"value\":\"1.983 x 700 x 1.090 mm\"},{\"label\":\"Khoảng cách trục bánh xe\",\"value\":\"1.312 mm\"},{\"label\":\"Độ cao yên\",\"value\":\"788 mm\"},{\"label\":\"Khoảng sáng gầm xe\",\"value\":\"151 mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000km (tùy điều kiện nào đến trước)\"}]}]', '<p>Cbr150r không chỉ là một chiếc xe máy thể thao mà còn là biểu tượng của phong cách sống hiện đại, đáp ứng nhu cầu di chuyển linh hoạt và thời thượng của giới trẻ ngày nay.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>MUA XE HONDA CBR150R KHUYẾN MÃI MỚI NHẤT HIỆN NAY&nbsp;</h2>\n<p>Với khối động cơ DOHC 150cc mạnh mẽ, <b>cbr 150r</b> không chỉ mang đến hiệu suất vận hành ấn tượng mà còn đảm bảo sự an toàn và tiện ích tối ưu cho người lái. Đây chính là mẫu xe thể thao hoàn hảo, thể hiện tinh thần đam mê và phong cách sống năng động của thương hiệu Honda.</p>\n\n<p><b>Honda cbr 150</b> không chỉ đơn thuần là một phương tiện di chuyển; nó là một phần không thể thiếu trong cuộc sống của những ai yêu thích sự tự do và khám phá. Thiết kế tinh tế cùng với công nghệ tiên tiến giúp xe hoạt động mượt mà, mang lại cảm giác phấn khích mỗi khi bạn cầm lái.</p>\n<p>Hãy cùng Hùng Phát tìm hiểu sâu hơn về dòng xe <b>cbr150r honda</b> này trong bài viết dưới đây để khám phá những điểm nổi bật và lý do tại sao <b>cbr 150r </b>lại trở thành lựa chọn hàng đầu cho những tín đồ yêu thích mô tô thể thao.</p>\n<h2>1. Điểm nổi bật trong thiết kế của dòng xe Honda CBR 150R</h2>\n<p><em>Thiết kế thể thao ấn tượng với phối màu mới</em></p>\n<p><b>Xe cbr 150r </b>đã chính thức ra mắt với những phối màu mới đầy ấn tượng, mang đến một diện mạo khỏe khoắn và năng động cho người lái. Thiết kế màu sơn trên thân xe được chăm chút tỉ mỉ, không chỉ tạo hiệu ứng thị giác mạnh mẽ mà còn thể hiện phong cách cá nhân độc đáo của từng chủ sở hữu.</p>\n<p>Phiên bản Thể thao gây ấn tượng mạnh với gam màu đỏ rực rỡ, kết hợp hoàn hảo với mặt nạ trước màu trắng và vành xe màu vàng nổi bật. Sự kết hợp này không chỉ tạo nên vẻ ngoài cuốn hút mà còn thể hiện tinh thần thể thao mạnh mẽ.</p>\n<p>Trong khi đó, phiên bản Đặc biệt của <strong>xe cbr 150r</strong> mang đến sự sang trọng với sắc đen nhám huyền bí, được tô điểm bằng vành xe màu nâu nổi bật, tạo nên sự khác biệt đầy thu hút.</p>\n\n<p>Cuối cùng, phiên bản Tiêu chuẩn trẻ trung tận dụng tối đa hai tông màu đỏ và đen, mang lại cảm giác trẻ trung và năng động cho người sử dụng. Tất cả các phiên bản đều hứa hẹn sẽ làm hài lòng những tín đồ yêu thích tốc độ và phong cách thể thao</p>\n<p><em>Hệ thống đèn LED hiện đại</em></p>\n<p><b>Cbr150r </b>được trang bị hệ thống chiếu sáng toàn bộ bằng đèn LED, giúp tăng cường khả năng chiếu sáng hiệu quả. Đèn phía trước được thiết kế tách thành hai tầng với chức năng riêng biệt: đèn ban ngày ở tầng trên và đèn pha/cos ở tầng dưới, đảm bảo an toàn tối đa trong mọi điều kiện ánh sáng.</p>\n\n<p><em>Giảm xóc hành trình ngược Up Side Down thể thao</em></p>\n<p>Với trang bị giảm xóc hành trình ngược Up Side Down, <b>honda cbr 150</b> khẳng định vị thế của mình như một mẫu xe côn tay thể thao lý tưởng cho đô thị. Phần giảm xóc được sơn mạ vàng không chỉ tạo nên vẻ đẹp sang trọng mà còn mang lại cảm giác cứng cáp và cao cấp cho toàn bộ phần đầu xe.</p>\n<p><em>Bình xăng trước với dung tích lớn và thiết tinh tế</em></p>\n<p>Bình xăng phía trước của<strong> cbr 150r</strong> có dung tích lên đến 12 lít, không chỉ mang lại khả năng chứa nhiên liệu tối ưu mà còn được thiết kế với những đường nét sắc cạnh, tạo nên vẻ ngoài gọn gàng và hiện đại. Thiết kế này không chỉ giúp tăng tính thẩm mỹ cho góc lái mà còn đảm bảo sự thoáng đãng, mang lại cảm giác thoải mái cho người điều khiển. Nhờ đó, người lái có thể tự tin khám phá mọi cung đường một cách dễ dàng và thuận tiện hơn.</p>\n<p><em>Bình xăng thiết kế tinh tế với dung tích lớn</em></p>\n<p>Bình xăng phía trước có dung tích lên tới 12 lít, được thiết kế với những đường nét sắc cạnh tinh tế. Điều này không chỉ giúp tối ưu hóa không gian mà còn tạo sự thoải mái cho người điều khiển trong suốt hành trình khám phá mọi cung đường.</p>\n<p><strong>Cbr150r</strong> không chỉ là một chiếc xe máy thể thao mà còn là biểu tượng của phong cách sống hiện đại, đáp ứng nhu cầu di chuyển linh hoạt và thời thượng của giới trẻ ngày nay.</p>\n<h2>2. Điểm nổi bật trong động cơ và tính năng của CBR 150</h2>\n<p><b>Cbr 150</b> không chỉ là một chiếc xe máy thể thao thông thường, mà còn là biểu tượng của sức mạnh và công nghệ tiên tiến trong phân khúc xe 150cc. Được trang bị động cơ DOHC với dung tích 150cc, <b>cbr150r</b> sở hữu cấu trúc xy-lanh đơn cùng hộp số 6 cấp, mang đến khả năng vận hành mạnh mẽ và linh hoạt. Đặc biệt, mô-men xoắn cực đại đạt 14,4 Nm tại vòng tua máy 7.000 vòng/phút giúp xe dễ dàng bứt phá trong mọi tình huống giao thông.</p>\n\n<p>Một trong những điểm nổi bật của <b>cbr 150</b> chính là bộ ly hợp hỗ trợ và chống trượt hai chiều. Tính năng này không chỉ giúp việc chuyển số trở nên mượt mà hơn mà còn giảm thiểu nguy cơ trượt bánh khi người lái thực hiện các thao tác về số đột ngột. Điều này mang lại sự an tâm cho người điều khiển, đặc biệt là trong những tình huống cần tăng tốc nhanh hoặc giảm tốc đột ngột.</p>\n<p>Ngoài ra, thiết kế khí động học tinh tế của <strong>xe cbr 150r</strong> cũng góp phần nâng cao hiệu suất vận hành và ổn định khi di chuyển ở tốc độ cao. Với sự kết hợp hoàn hảo giữa động cơ mạnh mẽ và các tính năng an toàn tiên tiến, <strong>cbr150r</strong> không chỉ đáp ứng nhu cầu di chuyển hàng ngày mà còn mang đến trải nghiệm lái xe đầy phấn khích cho những tín đồ yêu thích tốc độ.</p>\n<p><strong>Xe cbr 150r</strong> chính là lựa chọn lý tưởng cho những ai tìm kiếm một chiếc xe thể thao vừa mạnh mẽ vừa an toàn, phù hợp với nhiều loại địa hình và điều kiện giao thông khác nhau. Quý khách đang cần tham khảo <b>giá xe cbr 150</b> mới nhất hiện nay vui lòng liên hệ qua hotline để được tư vấn miễn phí.</p>\n<h2>3. Tiện ích hiện đại được trang bị trên dòng xe CBR 150R</h2>\n<p><em>Đồng hồ kỹ thuật số LCD tinh tế</em></p>\n<p><strong>Cbr150r honda</strong> được trang bị cụm đồng hồ kỹ thuật số LCD hiện đại, mang đến trải nghiệm lái xe tối ưu. Màn hình hiển thị rõ ràng các thông số quan trọng như tốc độ, vòng tua máy, cấp số, mức nhiên liệu và tín hiệu xi nhan. Thiết kế thông minh này giúp người lái dễ dàng theo dõi và điều chỉnh trong suốt quá trình vận hành.</p>\n\n<p><em>Hệ thống chống bó cứng phanh ABS tiên tiến</em></p>\n<p>Một trong những tính năng nổi bật của <b>cbr 150</b> là hệ thống chống bó cứng phanh ABS được trang bị cho cả bánh trước và bánh sau. Hệ thống này không chỉ nâng cao độ an toàn mà còn giúp người lái tự tin hơn khi xử lý các tình huống khẩn cấp trên đường. Với ABS, việc phanh gấp trở nên an toàn hơn, giảm thiểu nguy cơ trượt bánh và mất kiểm soát.</p>\n\n<p><em>Đèn tín hiệu dừng khẩn cấp ESS thông minh</em></p>\n<p>Dòng <b>xe cbr 150r </b>còn được trang bị hệ thống đèn cảnh báo dừng khẩn cấp (ESS), một tính năng hữu ích giúp tăng cường an toàn cho người lái. Khi xe phanh gấp, hệ thống này sẽ tự động kích hoạt đèn tín hiệu dừng khẩn cấp, cảnh báo cho các phương tiện xung quanh biết để có thể phản ứng kịp thời. Điều này không chỉ bảo vệ người lái mà còn góp phần đảm bảo an toàn cho tất cả các phương tiện tham gia giao thông.</p>\n<p>Với những tiện ích hiện đại này, <b>cbr 150</b> không chỉ là một chiếc xe máy thể thao mạnh mẽ mà còn là một người bạn đồng hành đáng tin cậy trên mọi nẻo đường.</p>\n<h2>4. Giá xe CBR 150 mới nhất hiện nay</h2>\n<p>Hiện tại, dòng xe <b>cbr 150r honda</b> đã có mặt đầy đủ các phiên bản và màu sắc tại cửa hàng xe máy Hùng Phát với <b>giá xe cbr 150</b> chỉ từ 70 triệu đồng. Đây là một trong những mẫu xe thể thao được yêu thích nhất trên thị trường, không chỉ bởi thiết kế bắt mắt mà còn bởi hiệu suất vượt trội. Nếu bạn đang tìm kiếm một địa chỉ <a href=\"/xe-may\"><strong>mua xe máy</strong></a> hoặc các dòng xe honda, đừng ngần ngại liên hệ ngay với hotline của chúng tôi để được tư vấn chi tiết và tận tình.</p>\n\n<p>Hệ thống xe máy Hùng Phát tự hào là đại lý chính hãng của năm thương hiệu nổi tiếng: Honda, Yamaha, Suzuki, SYM và xe điện Yadea. Chúng tôi cam kết mang đến cho khách hàng những sản phẩm chính hãng với chất lượng dịch vụ tốt nhất. Đội ngũ nhân viên chuyên nghiệp và nhiệt tình của chúng tôi luôn sẵn sàng hỗ trợ bạn trong việc lựa chọn chiếc xe phù hợp nhất với nhu cầu và sở thích cá nhân.</p>\n<p>Đến với <a href=\"/xe-may?nhom=honda\"><strong>cửa hàng xe máy</strong></a> Hùng Phát, bạn sẽ không chỉ tìm thấy những mẫu <b>xe </b><b>cbr 150r</b> mà còn được trải nghiệm dịch vụ chăm sóc khách hàng tận tâm. Hãy liên hệ ngay qua hotline để được cập nhật <b>giá xe cbr 150</b> mới nhất hiện nay và nhận được những ưu đãi hấp dẫn.</p>\n<p><strong>HỆ THỐNG XE MÁY HÙNG PHÁT&nbsp;</strong></p>', 1);
