INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dien-ocean', 'Xe điện Ocean', 'yadea', '[\"xe-may-dien\"]', 16990000, 17990000, '/sites/hungphat/img/2024/11/yadea-ocean-mau-xanh-la-truc.webp', '[\"/sites/hungphat/img/2024/11/yadea-ocean-mau-xanh-la-truc.webp\"]', '[\"Trắng Hồng gấu dâu\",\"Xanh lá trúc\"]', '[{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Trắng Hồng gấu dâu\"}],\"img\":\"/sites/hungphat/img/2024/11/yadea-ocean-gau-dau.webp\",\"price\":17990000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xanh lá trúc\"}],\"img\":\"/sites/hungphat/img/2024/11/yadea-ocean-mau-xanh-la-truc.webp\",\"price\":16990000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Loại động cơ\",\"value\":\"Động cơ điện một chiều không chổi than\"},{\"label\":\"Công suất danh định\",\"value\":\"800W\"},{\"label\":\"Công suất tối đa\",\"value\":\"1600W\"},{\"label\":\"Tốc độ tối đa\",\"value\":\"46km/h\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Loại vành\",\"value\":\"MT2.15×10/ J10x2.15\"},{\"label\":\"Đường kính vành trước/sau\",\"value\":\"10/10 inch\"},{\"label\":\"Hệ thống phanh\",\"value\":\"Phanh đĩa/ Tang trống\"},{\"label\":\"Loại lốp\",\"value\":\"MT2.15×10/ J10x2.15\"},{\"label\":\"Thông số lốp (trước/sau)\",\"value\":\"10/10 inch\"},{\"label\":\"Hệ thống đèn\",\"value\":\"LED\"},{\"label\":\"Chế độ lái\",\"value\":\"Eco/Sport\"},{\"label\":\"Tổ hợp nút bấm\",\"value\":\"Cụm công tắc trái:công tắc đèn chiếu xa gần, xi nhan, còi. Cụm công tắc phải: Nút Parking, nút chế độ lái, công tắc đèn, công tắc đèn ưu tiên.\"},{\"label\":\"Cách khởi động xe\",\"value\":\"Mở khóa bằng remote hoặc khóa cơ\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Dài x rộng x cao (mm)\",\"value\":\"1650×710×1030mm\"},{\"label\":\"Màn hình\",\"value\":\"Mà hình tinh thể lỏng 6.2 inch\"},{\"label\":\"Khoảng sáng xe\",\"value\":\"130 mm\"},{\"label\":\"Chiều cao yên\",\"value\":\"710 mm\"},{\"label\":\"Khối lượng bản thân\",\"value\":\"93 Kg\"},{\"label\":\"Khối lượng cho phép chở\",\"value\":\"130 Kg\"},{\"label\":\"Dung tích cốp xe\",\"value\":\"18 L\"},{\"label\":\"Trọng Lượng/ Kích thước PIN/ẮC QUY\",\"value\":\"7Kg*5 bình\"},{\"label\":\"Dung lượng ắc quy\",\"value\":\"60V22Ah\"},{\"label\":\"Thời gian sạc\",\"value\":\"7-8 tiếng\"},{\"label\":\"Độ dài quãng đường\",\"value\":\"80 km\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Khách hàng mua xe điện chính hãng Yadea được bảo dưỡng miễn phí 5 lần trong 12 tháng kể từ ngày khách hàng mua xe\",\"value\":\"Lần 1: 300km/1 tháng ; Lần 2: 2500km/ 3 tháng; Lần 3: 5000km/ 6 tháng; Lần 4: 7500km/ 9 tháng; Lần 5: 10000km/12 tháng\"},{\"label\":\"Thời gian bảo hành\",\"value\":\"Tùy theo điều kiện nào đến trước.Yadea khuyến khích khách hàng bảo dưỡng định kỳ thường xuyên để nâng cao công năng sử dụng của xe cũng như kiểm soát được hành trình khi di chuyển trên đường.\"}]}]', '<p>Xe Yadea Ocean mang đến nhiều lựa chọn: xanh ngọc trẻ trung, đỏ rực rỡ, đen nhám cá tính, xám bạc sang trọng… Nhờ đó, mỗi người dễ dàng tìm được phiên bản hợp với phong cách riêng.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>YADEA OCEAN – DÒNG XE MÁY ĐIỆN THỜI TRANG, GIÁ RẺ</h2>\n<p>Bạn đang tìm một mẫu <a href=\"/xe-may\"><b>xe máy điện</b></a> vừa thời trang, vừa tiết kiệm chi phí, lại thân thiện với môi trường? <b>Xe điện Yadea Ocean</b> chính là lựa chọn lý tưởng. Thiết kế trẻ trung, màu sắc nổi bật cùng động cơ mạnh mẽ giúp bạn di chuyển thoải mái, an toàn và tiết kiệm.</p>\n<h2>1. Thiết kế trẻ trung và động cơ vượt trội của Yadea Ocean</h2>\n<p>Ngay từ cái nhìn đầu tiên, <b>yadea ocean</b> gây ấn tượng với phong cách tối giản nhưng hiện đại. Đường nét mềm mại, đèn LED trước – sau sắc nét giúp xe nổi bật trong mọi khung cảnh. Thân xe gọn gàng, dễ điều khiển, rất phù hợp khi di chuyển ở các thành phố đông đúc.</p>\n<p>Phần yên xe dài, êm ái, thích hợp cho cả người lái và người ngồi sau. Chiều cao yên hợp lý, trọng lượng xe nhẹ, giúp cả nam và nữ đều dễ dàng điều khiển. Đây chính là lý do <b>xe yadea ocean</b> được giới trẻ, sinh viên và các gia đình trẻ lựa chọn.</p>\n<p>Về hiệu suất, <b>xe điện yadea ocean</b> trang bị động cơ công suất 1.200W, tốc độ tối đa khoảng 45 km/h, vừa đủ cho nhu cầu đi học, đi làm hoặc dạo phố cuối tuần. Pin lithium cao cấp giúp <b>xe máy điện yadea ocean</b> di chuyển quãng đường 70–80 km cho mỗi lần sạc. Thời gian sạc chỉ 6–8 giờ, thuận tiện cho người bận rộn. Công nghệ chống nước IPX7 bảo vệ động cơ khi đi dưới mưa, giúp xe vận hành ổn định trên nhiều loại địa hình.</p>\n<p>Đặc biệt, hệ thống treo và giảm xóc hiện đại đem đến cảm giác lái êm ái. Đây là ưu điểm lớn khi so sánh với nhiều dòng xe điện phổ thông khác trên thị trường. Nhờ đó, người dùng có thể di chuyển liên tục mà vẫn cảm thấy thoải mái.</p>\n<h2>2. Tiết kiệm chi phí và bảo vệ môi trường của xe điện Ocean</h2>\n<p>Một trong những lý do khiến nhiều người lựa chọn <b>xe máy điện ocean</b> chính là khả năng tiết kiệm chi phí đáng kể. Sạc đầy pin chỉ tốn chi phí bằng một phần nhỏ so với việc đổ xăng cho xe máy truyền thống. Với quãng đường 70–80 km cho mỗi lần sạc, bạn có thể di chuyển cả tuần trong nội thành mà không phải lo lắng về tiền nhiên liệu.</p>\n<p>Ngoài ra, việc sử dụng điện thay vì xăng giúp <b>xe điện ocean</b> không phát thải khí độc hại, góp phần bảo vệ môi trường và giảm thiểu ô nhiễm không khí. Trong bối cảnh các thành phố lớn đang thúc đẩy xu hướng di chuyển xanh, đây là một giải pháp thân thiện và bền vững.</p>\n<p>Nếu so sánh với một chiếc xe tay ga chạy xăng, mức chi phí vận hành của <b>xe điện yadea ocean</b> chỉ bằng khoảng 1/5. Bên cạnh đó, động cơ điện ít chi tiết chuyển động hơn, giúp giảm chi phí bảo dưỡng. Không cần thay dầu nhớt định kỳ, không lo các bộ phận động cơ nóng quá mức, người dùng tiết kiệm cả thời gian lẫn tiền bạc.</p>\n<h2>3. Tiện nghi, an toàn và màu sắc đa dạng của Yadea Ocean</h2>\n<p>Hãng Yadea trang bị cho <b>xe máy điện yadea ocean</b> nhiều công nghệ hiện đại nhằm nâng cao trải nghiệm và đảm bảo an toàn:</p>\n<ul>\n<li>Hệ thống phanh đĩa trước, phanh cơ sau cho lực phanh ổn định, phản hồi nhanh.</li>\n<li>Giảm xóc thủy lực cao cấp giúp xe di chuyển êm trên mặt đường gồ ghề.</li>\n<li>Bảng đồng hồ điện tử hiển thị tốc độ, dung lượng pin và quãng đường rõ ràng, hỗ trợ người lái kiểm soát hành trình.</li>\n<li>Đèn LED siêu sáng giúp đảm bảo tầm nhìn vào ban đêm, đồng thời tiết kiệm điện.</li>\n</ul>\n<p>Về màu sắc, <b>xe yadea ocean</b> mang đến nhiều lựa chọn: xanh ngọc trẻ trung, đỏ rực rỡ, đen nhám cá tính, xám bạc sang trọng… Nhờ đó, mỗi người dễ dàng tìm được phiên bản hợp với phong cách riêng. Dù yêu thích sự nổi bật hay tối giản, <b>xe điện yadea ocean</b> đều đáp ứng hoàn hảo.</p>\n<p>Thiết kế thân thiện cũng giúp việc vệ sinh, bảo dưỡng đơn giản hơn. Người dùng chỉ cần lau rửa định kỳ và sạc pin đúng cách để duy trì tuổi thọ. Đây là ưu điểm quan trọng với những ai muốn phương tiện gọn gàng, ít phải chăm sóc.</p>\n<h2>4. Mua xe Yadea Ocean chính hãng tại Xe máy Hùng Phát</h2>\n<p>Khi quyết định sở hữu <a href=\"/xe-may?nhom=yadea\"><b>xe điện yadea</b></a>, chọn đại lý uy tín là điều rất quan trọng. Hệ thống xe máy Hùng Phát – một trong những đại lý xe máy lớn và nổi tiếng tại TP.HCM – chính là địa chỉ đáng tin cậy:</p>\n<ul>\n<li>Trưng bày đầy đủ các phiên bản mới nhất của xe máy điện ocean và nhiều dòng xe điện khác.</li>\n<li>Đội ngũ tư vấn giàu kinh nghiệm, sẵn sàng giải đáp mọi thắc mắc và hỗ trợ lựa chọn màu sắc, phiên bản phù hợp nhu cầu.</li>\n<li>Chương trình khuyến mãi, hỗ trợ trả góp linh hoạt, giúp khách hàng dễ dàng sở hữu xe mà không cần thanh toán toàn bộ ngay từ đầu.</li>\n<li>Dịch vụ bảo hành, hậu mãi tận tâm, phụ tùng chính hãng, mang lại sự an tâm tuyệt đối.</li>\n</ul>\n<p>Không chỉ cung cấp <b>xe điện yadea ocean</b>, Hệ thống xe máy Hùng Phát còn nổi tiếng là nơi phân phối nhiều dòng xe máy chất lượng, từ xe tay ga đến xe số. Khách hàng có thể yên tâm về giá bán minh bạch, chính sách bảo dưỡng chuyên nghiệp và dịch vụ chăm sóc khách hàng chu đáo.</p>\n<p>Đặc biệt, đại lý này thường xuyên tổ chức các buổi trải nghiệm lái thử, cho phép bạn trực tiếp cảm nhận khả năng vận hành của <b>xe máy điện yadea ocean</b> trước khi quyết định mua. Đây là lợi thế lớn mà ít cửa hàng nhỏ lẻ nào có được. Liên hệ ngay qua hotline 0789.619.698 để được tư vấn miễn phí!</p>', 1);
