INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dien-orla', 'Xe điện Orla', 'yadea', '[\"xe-may-dien\"]', 19990000, 20990000, '/sites/hungphat/img/2024/11/orla-mau-trang-hong-gau-dau.webp', '[\"/sites/hungphat/img/2024/11/orla-mau-trang-hong-gau-dau.webp\"]', '[\"Hồng Trắng gấu dâu\",\"Nâu trà sữa\",\"Trắng\",\"Trắng Hồng gấu dâu\",\"Xám tinh vân\"]', '[{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Hồng Trắng gấu dâu\"}],\"img\":\"/sites/hungphat/img/2024/11/orla-mau-hong-trang-gau-dau.webp\",\"price\":20990000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Trắng Hồng gấu dâu\"}],\"img\":\"/sites/hungphat/img/2024/11/orla-mau-trang-hong-gau-dau.webp\",\"price\":20990000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Nâu trà sữa\"}],\"img\":\"/sites/hungphat/img/2024/11/orla-mau-trang-hong-gau-dau.webp\",\"price\":19990000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Trắng\"}],\"img\":\"/sites/hungphat/img/2024/11/orla-mau-trang.webp\",\"price\":19990000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xám tinh vân\"}],\"img\":\"/sites/hungphat/img/2024/11/orla-mau-xam-tinh-van.webp\",\"price\":19990000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Loại động cơ\",\"value\":\"Hub\"},{\"label\":\"Công suất danh định\",\"value\":\"800 W\"},{\"label\":\"Công suất tối đa\",\"value\":\"1700 W\"},{\"label\":\"Tốc độ tối đa\",\"value\":\"48 Km/h\"},{\"label\":\"Loại ắc quy\",\"value\":\"Ắc quy Graphene TTFAR\"},{\"label\":\"Chế độ lái\",\"value\":\"TTFAR/SPORT\"},{\"label\":\"Cách khởi động xe\",\"value\":\"Bluetooth và Khóa núm xoay/ Remote/ Chìa khoá cơ\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Loại vành\",\"value\":\"MT2.15X12/MT2.15X12\"},{\"label\":\"Đường kính vành trước/sau\",\"value\":\"12/12inch\"},{\"label\":\"Hệ thống phanh\",\"value\":\"Trước đĩa/ Sau tang chống\"},{\"label\":\"Loại lốp\",\"value\":\"Lốp không săm\"},{\"label\":\"Thông số lốp (trước/sau)\",\"value\":\"Trước 90/80-12 | sau 90/80-12\"},{\"label\":\"Hệ thống đèn\",\"value\":\"FULL LED\"},{\"label\":\"Tính Năng\",\"value\":\"Hệ thống chống trộm, Cảnh báo lăn bánh, Remote khởi động từ xa/tìm xe, Cổng sạc USB\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Dài x rộng x cao (mm)\",\"value\":\"1810 ×670×1140 mm\"},{\"label\":\"Màn hình\",\"value\":\"Màn hình tinh thể lỏng 5.91 inch\"},{\"label\":\"Khoảng sáng xe\",\"value\":\"180 mm\"},{\"label\":\"Chiều cao yên\",\"value\":\"760 mm\"},{\"label\":\"Khối lượng bản thân\",\"value\":\"108 Kg\"},{\"label\":\"Khối lượng cho phép chở\",\"value\":\"130 Kg\"},{\"label\":\"Dung tích cốp xe\",\"value\":\"17 L\"},{\"label\":\"Dung lượng ắc quy\",\"value\":\"60V22Ah\"},{\"label\":\"Độ dài quãng đường\",\"value\":\"65 Kg-30Km/h: 65Km\"},{\"label\":\"Trọng Lượng/ Kích thước PIN/ẮC QUY\",\"value\":\"7.0±0.2kg*5\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Bảo dưỡng miễn phí 5 lần trong 12 tháng kể từ ngày khách hàng mua xe\",\"value\":\"Lần 1: 300km/1 tháng; Lần 2: 2500km/ 3 tháng; Lần 3: 5000km/ 6 tháng; Lần 4: 7500km/ 9 tháng; Lần 5: 10000km/12 tháng\"},{\"label\":\"Thời gian bảo hành\",\"value\":\"Tùy theo điều kiện nào đến trước.Yadea khuyến khích khách hàng bảo dưỡng định kỳ thường xuyên để nâng cao công năng sử dụng của xe cũng như kiểm soát được hành trình khi di chuyển trên đường.\"}]}]', '<p>Ngay từ cái nhìn đầu tiên, xe orla đã gây ấn tượng bởi kiểu dáng thanh lịch, mang đậm hơi thở châu Âu cổ điển.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>XE ĐIỆN YADEA ORLA – ĐẦY THANH LỊCH VÀ SANG TRỌNG</h2>\n<p>Giữa hàng loạt mẫu xe điện trên thị trường, <b>Yadea Orla</b> nổi bật nhờ thiết kế thanh lịch, đậm chất cổ điển nhưng vẫn giữ trọn sự sang trọng hiện đại. Tại Hùng Phát, mẫu xe này đang là một trong những lựa chọn được nhiều khách hàng ưu ái khi tìm kiếm sự kết hợp hoàn hảo giữa thẩm mỹ và tiện ích.</p>\n<h2><b>1. Thiết kế cổ điển đậm chất châu Âu</b></h2>\n<p>Ngay từ cái nhìn đầu tiên, <b>xe orla</b> đã gây ấn tượng bởi kiểu dáng thanh lịch, mang đậm hơi thở châu Âu cổ điển. Phần đầu xe bo tròn, đèn pha LED dạng tròn cổ điển kết hợp cùng viền crom sáng bóng, gợi nhớ đến những chiếc Vespa Ý nổi tiếng. Tuy nhiên, Orla không chỉ dừng lại ở nét hoài cổ, mà còn được cách tân bằng những chi tiết tinh xảo, mang lại vẻ hiện đại đầy sang trọng.</p>\n<p>Khung xe liền khối, các đường nét uốn lượn mềm mại tạo cảm giác hài hòa và cân đối. Đây là một trong những điểm nhấn khiến nhiều người đánh giá cao <b>xe máy điện orla</b>, không chỉ để di chuyển mà còn là một phụ kiện thời trang đúng nghĩa.</p>\n<h2><b>2. Trải nghiệm lái êm ái và tiện lợi</b></h2>\n<p>Không chỉ chú trọng vào thiết kế, <b>xe điện orla</b> còn được đánh giá cao về khả năng vận hành. Trang bị động cơ điện mạnh mẽ, xe cho khả năng tăng tốc mượt mà, vận hành ổn định ngay cả khi đi trong khu vực đông đúc. Pin Lithium dung lượng cao giúp xe di chuyển quãng đường dài chỉ với một lần sạc, đáp ứng tốt nhu cầu đi học, đi làm hay dạo phố cuối tuần.</p>\n<p>Hệ thống phanh đĩa trước – sau hiện đại giúp người lái an tâm hơn trong mọi tình huống. Ngoài ra, giảm xóc êm ái, yên xe rộng rãi, chỗ để chân thoải mái… tất cả đều mang đến trải nghiệm thoải mái cho người dùng. Đây chính là lý do nhiều khách hàng lựa chọn <b>xe điện yadea orla</b> khi tìm kiếm phương tiện đi lại cho cuộc sống hiện đại.</p>\n<h2><b>3. Lợi ích kinh tế và bảo vệ môi trường</b></h2>\n<p>Một trong những điểm cộng lớn của <b>giá xe yadea orla</b> chính là tính kinh tế vượt trội. So với xe chạy xăng truyền thống, xe điện tiết kiệm chi phí hơn rất nhiều. Chỉ với vài nghìn đồng tiền điện cho một lần sạc, bạn có thể di chuyển cả chục km, giảm đáng kể chi phí đi lại hằng ngày.</p>\n<p>Không chỉ tiết kiệm, xe còn hoàn toàn thân thiện với môi trường. Việc sử dụng <b>xe máy điện yadea orla</b> đồng nghĩa với việc bạn đang góp phần giảm lượng khí thải CO2 ra ngoài không khí, giúp bảo vệ bầu trời xanh, hạn chế ô nhiễm và mang lại một môi trường sống trong lành hơn cho cộng đồng.</p>\n<h2><b>4. Yadea Orla – Sự lựa chọn lý tưởng cho phong cách sống tinh tế</b></h2>\n<p>Đối tượng lựa chọn <b>xe điện yadea orla</b> vô cùng đa dạng. Sinh viên, học sinh cần một chiếc xe gọn nhẹ, tiết kiệm; nhân viên văn phòng mong muốn phương tiện thanh lịch và sang trọng; hay những tín đồ thời trang yêu thích sự nổi bật đều có thể tìm thấy ở Orla một người bạn đồng hành lý tưởng.</p>\n<p>Hơn thế nữa, với kiểu dáng cổ điển pha lẫn hiện đại, Orla phù hợp cho cả nam và nữ. Đây chính là sự khác biệt giúp xe không chỉ đơn thuần là phương tiện mà còn là tuyên ngôn phong cách cá nhân.</p>\n<h2><b>5. Mua xe điện Yadea Orla chính hãng tại Hùng Phát</b></h2>\n<p>Việc chọn mua xe điện không chỉ dừng lại ở mẫu mã đẹp hay công nghệ hiện đại, mà quan trọng nhất chính là chọn được địa chỉ uy tín để đảm bảo chất lượng và quyền lợi lâu dài. Với nhiều năm kinh nghiệm trong ngành xe máy và <a href=\"/xe-may\"><strong>xe điện</strong></a>, Hùng Phát đã trở thành địa chỉ tin cậy của hàng ngàn khách hàng.</p>\n<p>Khi lựa chọn <b>xe điện Yadea Orla</b> tại Hùng Phát, bạn sẽ nhận được sự đảm bảo về:</p>\n<ul>\n<li>Sản phẩm chính hãng 100%: Cam kết phân phối trực tiếp từ thương hiệu <a href=\"/xe/xe-dien-orla\"><strong>xe điện yadea</strong></a>, có đầy đủ giấy tờ chứng minh nguồn gốc rõ ràng.</li>\n<li>Chính sách bảo hành minh bạch: Khách hàng được hưởng đầy đủ chế độ bảo hành, bảo dưỡng theo đúng tiêu chuẩn của hãng.</li>\n<li>Mức giá cạnh tranh, hợp lý: Bảng giá luôn công khai, đi kèm nhiều chương trình khuyến mãi hấp dẫn, giúp bạn tiết kiệm chi phí khi mua xe.</li>\n<li>Dịch vụ hậu mãi chuyên nghiệp: Hỗ trợ bảo dưỡng định kỳ, thay thế linh kiện chính hãng nhanh chóng, tiện lợi.</li>\n<li>Đội ngũ nhân viên tận tâm: Sẵn sàng tư vấn chi tiết về từng phiên bản xe, giúp bạn chọn được mẫu xe phù hợp nhất với nhu cầu và ngân sách.</li>\n</ul>\n<p>Với phương châm “Khách hàng là trung tâm”, Hùng Phát không chỉ bán xe mà còn mang đến trải nghiệm mua sắm trọn vẹn, giúp bạn an tâm tuyệt đối trong suốt quá trình sử dụng. Đây chính là lý do mà nhiều khách hàng luôn ưu tiên chọn Hùng Phát làm nơi mua <b>xe điện Yadea Orla</b> cũng như các dòng xe điện và xe máy khác. Còn chờ gì mà không gọi đến hotline 0789.619.698 hoặc nhắn tin trực tiếp qua fanpage để được tư vấn!</p>', 1);
