INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-elite-50cc', 'Xe Elite 50cc', 'sym', '[]', 23900000, 23900000, '/sites/hungphat/img/2024/11/elite-50-mau-trang-den.webp', '[\"/sites/hungphat/img/2024/11/elite-50-mau-trang-den.webp\"]', '[\"Đen Đỏ\",\"Trắng Đen\"]', '[{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Đen Đỏ\"}],\"img\":\"/sites/hungphat/img/2024/11/elite-50-mau-den-do.webp\",\"price\":23900000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Trắng Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/elite-50-mau-trang-den.webp\",\"price\":23900000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Động cơ\",\"value\":\"4 thì\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"4.5L\"},{\"label\":\"Phân khối\",\"value\":\"49.5cc\"},{\"label\":\"Mức hao xăng\",\"value\":\"1.88L/100km\"},{\"label\":\"Công suất tối đa\",\"value\":\"2.7kw/8000 rpm\"},{\"label\":\"Momen cực đại\",\"value\":\"3.4Nm/ 7000 rpm\"},{\"label\":\"Hệ thống truyền động\",\"value\":\"Tự động vô cấp\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Đề/đạp\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Hệ thống thắng trước\",\"value\":\"Phanh trống (đùm)\"},{\"label\":\"Hệ thống thắng sau\",\"value\":\"Phanh trống (đùm)\"},{\"label\":\"Phuộc trước\",\"value\":\"Thủy lực\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ\"},{\"label\":\"Vỏ/lốp trước\",\"value\":\"Không ruột 90/90-10\"},{\"label\":\"Vỏ/lốp sau\",\"value\":\"Không ruột 90/90-10\"},{\"label\":\"Đèn pha\",\"value\":\"12V-35W/35W\"},{\"label\":\"Đèn định vị trước\",\"value\":\"12V-5W\"},{\"label\":\"Đèn sau, đèn thắng\",\"value\":\"12V-5W/21W\"},{\"label\":\"Đèn signal\",\"value\":\"12V-10W\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Dài - Rộng - Cao\",\"value\":\"1.725 x 690 x 1025mm\"},{\"label\":\"Khoảng cách gầm\",\"value\":\"100mmm\"},{\"label\":\"Khoảng cách 2 trục\",\"value\":\"1180 mm\"},{\"label\":\"Tổng trọng lượng khô/Tải trọng\",\"value\":\"84kg/130kg\"},{\"label\":\"Độ cao yên xe\",\"value\":\"740mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Bảo hành\",\"value\":\"24 tháng hoặc 30.000km\"}]}]', '<p>Xe tay ga 50cc sym elite không chỉ thu hút người dùng bởi thiết kế nhỏ gọn, tiện lợi mà còn bởi sự phong phú trong các phiên bản màu sắc.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>MUA XE TAY GA SYM ELITE 50CC GIÁ RẺ CHÍNH HÃNG</h2>\n<p><b>Elite 50cc</b> là một trong những dòng xe tay ga 50cc bán chạy nhất hiện nay của SYM. Với thiết kế hoài cổ đầy quyến rũ, <b>xe elite 50cc </b>không chỉ thu hút mọi ánh nhìn mà còn thể hiện sự nữ tính và thanh lịch. Dưới đây là những điểm nổi bật của <b>sym elite 50</b> và <b>giá xe elite 50 </b>giá rẻ chính hãng.</p>\n<h2>1. Những điểm nổi bật trong thiết kế của xe elite 50cc</h2>\n<p>Màu sắc đa dạng và thời thượng</p>\n<p><b>Xe tay ga 50cc sym elite</b> không chỉ thu hút người dùng bởi thiết kế nhỏ gọn, tiện lợi mà còn bởi sự phong phú trong các phiên bản màu sắc. Mỗi màu sắc đều mang đến một cá tính riêng, giúp người dùng dễ dàng lựa chọn theo sở thích và phong cách sống của mình.</p>\n<p><b>Elite 50cc </b>phiên bản màu xám đen trắng: Sự kết hợp hoàn hảo giữa ba gam màu xám, đen và trắng tạo nên vẻ ngoài thanh lịch và hiện đại. Phiên bản này rất phù hợp với những ai yêu thích sự tối giản nhưng vẫn muốn thể hiện nét sang trọng trong phong cách của mình.</p>\n<p><b>Elite 50</b> phiên bản màu xanh đen trắng: Màu sắc này mang lại cảm giác tươi mới và năng động, là lựa chọn lý tưởng cho giới trẻ yêu thích sự phá cách và muốn nổi bật giữa đám đông.</p>\n<p><b>Xe elite 50cc </b>phiên bản màu đen đỏ: Sự phối hợp mạnh mẽ giữa hai gam màu này tạo nên một diện mạo cá tính và cuốn hút. Đây là lựa chọn dành cho những ai muốn khẳng định phong cách riêng biệt của mình.</p>\n<p><b>Sym elite 50</b> phiên bản màu trắng đen: Màu trắng kết hợp với đen luôn là sự lựa chọn an toàn nhưng không kém phần tinh tế. Với phiên bản này, bạn có thể dễ dàng phối hợp với nhiều trang phục khác nhau mà vẫn giữ được vẻ thanh lịch.</p>\n<p>Mỗi phiên bản màu sắc của <b>xe elite 50cc</b> đều mang đến một phong cách độc đáo, giúp người dùng thể hiện cá tính riêng. Hãy đến ngay các đại lý SYM để trải nghiệm trực tiếp và tìm cho mình chiếc xe phù hợp nhất!</p>\n<p>Thiết kế nữ tính và thanh lịch</p>\n<p><b>Sym elite 50cc</b> được thiết kế theo phong cách thanh lịch, nhẹ nhàng với thân xe nhỏ gọn cùng những đường cong mềm mại. Diện mạo nữ tính của chiếc xe không chỉ thu hút ánh nhìn mà còn mang lại cảm giác thoải mái khi sử dụng.</p>\n<p>Một trong những điểm nhấn đáng chú ý chính của <b>xe tay ga 50cc sym elite</b> là hệ thống đèn pha và đèn hậu được thiết kế độc đáo. Sự kết hợp tinh tế giữa phong cách hiện đại và cổ điển tạo nên một diện mạo cuốn hút cho chiếc xe. Đèn pha trước sử dụng bóng Halogen mạnh mẽ, giúp tối ưu hóa tầm nhìn trong mọi điều kiện ánh sáng, đảm bảo an toàn cho người lái khi di chuyển vào ban đêm hoặc trong điều kiện thời tiết xấu.</p>\n<p>Cụm đồng hồ với thiết kế tròn đơn giản nhưng vẫn mang nét đẹp cổ điển như một món trang sức tinh tế cho xe. Tay lái nhỏ gọn tích hợp các nút điều khiển tiện dụng cùng gương chiếu hậu tròn cổ điển tạo nên sự hài hòa về mặt thẩm mỹ cũng như tiện lợi cho người sử dụng.</p>\n<p>Với tất cả những ưu điểm vượt trội trên, việc sở hữu một chiếc <b>xe elite 50cc</b> không chỉ đáp ứng nhu cầu di chuyển hàng ngày mà còn giúp bạn thể hiện phong cách sống đầy tự tin và thời trang. Đây chắc chắn sẽ là sự lựa chọn hoàn hảo cho phái đẹp đang tìm kiếm một phương tiện vừa tiện lợi vừa thời thượng trong cuộc sống hàng ngày. Hãy để <b>sym elite 50</b> đồng hành cùng bạn trên mọi nẻo đường!</p>\n<h2>2. Tiện ích nổi bật của xe máy Elite 50cc</h2>\n<p>Xe máy <b>elite 50cc</b> không chỉ thu hút người dùng bởi thiết kế hiện đại, thời trang mà còn mang đến nhiều tiện ích vượt trội, đáp ứng nhu cầu sử dụng hàng ngày một cách hoàn hảo. Dưới đây là những điểm nổi bật khiến<b> xe elite 50cc</b> trở thành sự lựa chọn lý tưởng cho người tiêu dùng.</p>\n<p>Thiết kế móc treo đồ thông minh</p>\n<p>Một trong những tính năng tiện lợi nhất của <b>elite 50</b> chính là móc treo đồ được tích hợp ngay phía trước xe, dưới yếm. Móc treo này giúp người dùng dễ dàng treo các vật dụng cá nhân như túi xách, nón bảo hiểm hay các đồ dùng khác mà không lo bị rơi rớt. Điều này đặc biệt hữu ích trong những chuyến đi ngắn hoặc khi bạn cần mang theo nhiều đồ đạc.</p>\n<p>Hệ thống ổ khóa đa chức năng</p>\n<p><b>Xe sym elite</b> được trang bị ổ khóa thông minh với bốn chức năng: công tắc điện, khóa cổ, mở nắp bình xăng và khóa từ chống trộm. Thiết kế này không chỉ nâng cao tính an toàn cho xe mà còn mang lại sự thuận tiện tối đa cho người sử dụng. Bạn có thể yên tâm hơn khi để xe ở nơi công cộng mà không lo lắng về vấn đề an ninh.</p>\n<p>Nắp bình xăng tiện lợi</p>\n<p>Nắp bình xăng của <strong>xe elite 50cc</strong> được bố trí ở bên ngoài, phía sau yên xe, giúp việc đổ xăng trở nên dễ dàng hơn bao giờ hết. Người dùng không cần phải mở yên xe để tiếp nhiên liệu, tiết kiệm thời gian và công sức trong những lúc gấp gáp.</p>\n<p>Sàn để chân rộng rãi</p>\n<p>Sàn để chân của <b>sym elite 50</b> được thiết kế rộng và phẳng, tạo cảm giác thoải mái cho người lái trong suốt hành trình. Điều này đặc biệt quan trọng khi di chuyển trên quãng đường dài hoặc trong điều kiện giao thông đông đúc. Sự thoải mái này giúp giảm mệt mỏi và tăng cường trải nghiệm lái xe.</p>\n<p>Yên xe sang trọng và thoải mái</p>\n<p>Yên xe của <b>sym elite 50cc</b> được thiết kế rộng rãi với lớp bọc giả da mềm mại, đủ chỗ cho hai người ngồi thoải mái. Cốp dưới yên cũng rất rộng rãi, có khả năng chứa hai chiếc mũ bảo hiểm nửa đầu cùng một số vật dụng cá nhân khác. Đây là một điểm cộng lớn đối với phái đẹp khi lựa chọn chiếc<strong> xe elite 50cc</strong> vì sự tiện lợi và phong cách.</p>\n<p>Động cơ mạnh mẽ và tiết kiệm nhiên liệu</p>\n<p>Động cơ của <b>xe sym elite</b> được chế tạo theo tiêu chuẩn kỹ thuật cao với dung tích chính xác là 49,5cc. Công suất tối đa đạt 2,7kW tại vòng tua máy 8000 vòng/phút và mô men xoắn cực đại đạt 3,4Nm tại vòng tua máy 7000 vòng/phút. Với hiệu suất mạnh mẽ cùng khả năng tiết kiệm nhiên liệu vượt trội, <strong>elite 50cc</strong> sẽ đồng hành cùng bạn bền bỉ qua thời gian.</p>\n<h2>3. Mua xe máy Etile 50cc giá rẻ tại Hùng Phát</h2>\n<p>Hiện tại, <a href=\"/xe-may\"><b>đại lý xe máy</b></a> Hùng Phát đang cung cấp đầy đủ các phiên bản màu sắc của dòng <b>Xe tay ga 50cc sym elite</b>. Nếu bạn đang tìm kiếm thông tin về <b>giá xe elite 50</b> hoặc muốn khám phá thêm các dòng xe 50cc khác từ thương hiệu SYM, đừng ngần ngại liên hệ với chúng tôi để nhận được những ưu đãi hấp dẫn.</p>\n<p>Hiện tại, <b>giá xe elite 50 </b>ở Hùng Phát đang chỉ từ 23.900.000đ</p>\n<p>Hệ thống xe máy Hùng Phát cam kết hỗ trợ khách hàng tối đa với chương trình mua xe trả góp chỉ với 0đ, giúp bạn dễ dàng sở hữu xe máy <b>elite 50cc</b> mơ ước mà không gặp bất kỳ trở ngại nào về tài chính. Ngoài ra, khi mua xe tại Hùng Phát, quý khách sẽ được nhận ngay quà tặng hấp dẫn trị giá lên đến 2.350.000 đồng.</p>\n<p>Tại Hệ thống xe máy Hùng Phát, chất lượng và nguồn gốc sản phẩm luôn được đảm bảo thông qua chế độ bảo hành chính hãng. Chúng tôi tự hào mang đến cho khách hàng dịch vụ giao xe tận nhà nhanh chóng và tiện lợi, giúp tiết kiệm thời gian và công sức cho bạn.</p>\n<p>Đội ngũ tư vấn viên chuyên nghiệp của chúng tôi luôn sẵn sàng hỗ trợ bạn mọi lúc mọi nơi với dịch vụ tư vấn online hoạt động 24/7. Không chỉ dừng lại ở dòng<b> xe etile 50cc</b>, Hùng Phát còn cung cấp đa dạng các loại xe máy khác để đáp ứng nhu cầu phong phú của khách hàng.</p>\n<p>Đừng bỏ lỡ cơ hội sở hữu chiếc xe<b> elite 50</b> yêu thích với những ưu đãi đặc biệt từ Hùng Phát. Liên hệ <a href=\"/xe-may?nhom=sym\"><b>cửa hàng sym</b></a> Hùng Phát ngay hôm nay để được tư vấn miễn phí và trải nghiệm dịch vụ tuyệt vời!</p>\n<p><strong>HỆ THỐNG XE MÁY HÙNG PHÁT&nbsp;</strong></p>', 1);
