INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-future', 'Xe Future', 'honda', '[\"xe-so\"]', 33800000, 36600000, '/sites/hungphat/img/2024/11/future-phien-ban-dac-biet-mau-xanh-den.webp', '[\"/sites/hungphat/img/2024/11/future-phien-ban-dac-biet-mau-xanh-den.webp\"]', '[\"Đen Vàng\",\"Đỏ Đen\",\"Trắng Đen\",\"Xanh đậm Đen\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh đậm Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/future-phien-ban-cao-cap-mau-xanh-den.webp\",\"price\":36300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/future-phien-ban-cao-cap-mau-do-den.webp\",\"price\":36300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Trắng Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/future-phien-ban-cao-cap-mau-trang-den.webp\",\"price\":36600000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh đậm Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/future-phien-ban-dac-biet-mau-xanh-den.webp\",\"price\":36300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Vàng\"}],\"img\":\"/sites/hungphat/img/2024/11/future-phien-ban-dac-biet-mau-den-vang.webp\",\"price\":36300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh đậm Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/future-phien-ban-tieu-chuan-mau-xanh-den.webp\",\"price\":33800000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Dung tích bình xăng\",\"value\":\"4,6 L\"},{\"label\":\"Loại động cơ\",\"value\":\"Xăng 4 kỳ, 1 xi lanh làm mát bằng không khí\"},{\"label\":\"Công suất tối đa\",\"value\":\"6,83 kW / 7.500 vòng/phút\"},{\"label\":\"Dung tích nhớt máy\",\"value\":\"Sau khi xả 0,7 lít Sau khi rã máy 0,9 lít\"},{\"label\":\"Mức tiêu thụ nhiên liệu\",\"value\":\"1,47 Lít/100km\"},{\"label\":\"Hộp số\",\"value\":\"4 số tròn\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Đạp chân / Điện\"},{\"label\":\"Moment cực đại\",\"value\":\"10,2 Nm / 5.500 vòng/phút\"},{\"label\":\"Dung tích xy-lanh\",\"value\":\"124,9 cm3\"},{\"label\":\"Đường kính x Hành trình pít tông\",\"value\":\"52,400 x 57,913 mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"9,3 : 1\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Kích cỡ lốp trước/ sau\",\"value\":\"Lốp trước: 70/90-17M/C 38P Lốp sau: 80/90-17M/C 50P\"},{\"label\":\"Phuộc trước\",\"value\":\"Ống lồng, giảm chấn thủy lực\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ, giảm chấn thủy lực\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Khối lượng bản thân\",\"value\":\"104 kg\"},{\"label\":\"Dài x Rộng x Cao\",\"value\":\"1.931 x 711 x 1.083mm\"},{\"label\":\"Khoảng cách trục bánh xe\",\"value\":\"1.258 mm\"},{\"label\":\"Độ cao yên\",\"value\":\"756 mm\"},{\"label\":\"Khoảng sáng gầm xe\",\"value\":\"133 mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000km (tùy điều kiện nào đến trước)\"}]}]', '<p>Honda future không chỉ nổi bật với thiết kế hiện đại mà còn được trang bị nhiều tiện ích thông minh, mang lại sự tiện lợi và an toàn cho người sử dụng.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>MUA XE FUTURE GIÁ RẺ CHÍNH HÃNG CỦA HONDA&nbsp;</h2>\n<p><b>Honda future</b> đã khẳng định vị thế của mình là một trong những dòng xe số bán chạy nhất. Với thiết kế mạnh mẽ và tinh tế,<b> xe future</b> không chỉ mang đến trải nghiệm lái tuyệt vời mà còn thể hiện phong cách sống đẳng cấp của người sử dụng. Mỗi chi tiết trên <b>xe fu</b> đều được chăm chút tỉ mỉ, từ kiểu dáng cho đến các tính năng tiên tiến, nhằm mang lại sự hài lòng tối đa cho người tiêu dùng.</p>\n\n<p>Nếu bạn đang tìm kiếm một chiếc xe máy mạnh mẽ và bền bỉ, hãy liên hệ ngay với Hùng Phát để được tư vấn miễn phí về <b>giá xe future</b>. Với mức giá hợp lý cùng độ bền vượt trội,<b> future 125 fi </b>chắc chắn sẽ trở thành người bạn đồng hành lý tưởng trên mọi nẻo đường.</p>\n<h2>1. Sự kết hợp giữa thiết kế hiện đại và sang trọng của dòng xe Future</h2>\n<p><b>Xe future </b>là một trong những mẫu xe nổi bật của thương hiệu Honda, với những đường nét hiện đại, thanh lịch cùng với tính năng vượt trội, <b>xe fu</b> đã khẳng định được vị của mình trên thị trường xe máy Việt Nam.</p>\n\n<p>Thiết kế của future 125 fi</p>\n<p><b>Future 125 fi</b> không chỉ đơn thuần là một phương tiện di chuyển, mà còn là biểu tượng của sự sang trọng, trẻ trung và lịch lãm. Với kiểu dáng tổng thể tinh tế, chiếc xe này nổi bật với những chi tiết thiết kế tỉ mỉ và sắc nét. Từ logo đến mặt đồng hồ, hệ thống đèn cho đến các chi tiết mạ cờ-rôm cao cấp, tất cả đều góp phần tạo nên một diện mạo ấn tượng và cuốn hút cho chủ sở hữu.</p>\n<p>Hệ thống đèn pha LED đẳng cấp</p>\n<p>Cụm đèn pha LED được thiết kế nổi bật không chỉ mang lại vẻ đẹp hiện đại mà còn đảm bảo hiệu suất chiếu sáng tối ưu. Với công nghệ LED tiên tiến, đèn pha không chỉ có tuổi thọ cao mà còn tiết kiệm năng lượng hiệu quả. Cường độ ánh sáng mạnh mẽ giúp nâng cao khả năng quan sát trong điều kiện ánh sáng yếu, đồng thời tạo nên hình ảnh sang trọng và thu hút mọi ánh nhìn.</p>\n<p>Logo “Future” 3D tinh xảo</p>\n<p>Điểm nhấn đặc biệt trên <b>future 125 fi</b> chính là logo “Future” 3D được chế tác tinh xảo. Thiết kế này không chỉ mang lại cảm giác hiện đại mà còn khẳng định phong cách riêng biệt của chiếc xe, khiến nó trở thành lựa chọn lý tưởng cho những ai yêu thích sự khác biệt.</p>\n\n<p>Màu xe tinh tế và hiện đại</p>\n<p><b>Xe future</b> ra mắt với ba phiên bản màu sắc mới mẻ, được áp dụng cách phối màu tinh tế trên các chi tiết như yếm xe, tay dắt sau, mặt ốp trong xe và giảm xóc. Sự kết hợp hài hòa này mang đến một hình ảnh tổng thể trẻ trung và hiện đại, phù hợp với xu hướng thời trang hiện nay.</p>\n<p>Với thiết kế sang trọng, tính năng vượt trội và giá xe ưu đãi, <b>mua xe future</b> chắc chắn sẽ làm hài lòng ngay cả những khách hàng khó tính nhất.</p>\n<h2>2. Động cơ mạnh mẽ và tính vượt trội của Honda Future</h2>\n<p><b>Honda future</b> không chỉ là một phương tiện di chuyển mà còn là biểu tượng cho sự kết hợp hoàn hảo giữa sức mạnh động cơ và tính năng tiết kiệm nhiên liệu. Đây chính là lý do khiến mẫu xe này luôn được yêu mến và tin tưởng bởi đông đảo khách hàng tại Việt Nam.</p>\n<p>Động cơ 125cc đẳng cấp</p>\n<p><b>Future 125 fi</b> tự hào sở hữu động cơ 125cc nổi tiếng, đã khẳng định được vị thế vững chắc trong lòng người tiêu dùng Việt Nam. Động cơ này không chỉ duy trì chất lượng cao mà còn được trang bị hệ thống lọc gió tiên tiến, giúp tối ưu hóa công suất và mô-men xoắn cực đại. Nhờ đó, khả năng tăng tốc của xe trở nên mạnh mẽ và linh hoạt hơn bao giờ hết.</p>\n<p>Khả năng tiết kiệm nhiên liệu vượt trội</p>\n\n<p>Một trong những điểm nổi bật nhất của Honda Future 125 FI chính là khả năng tiết kiệm nhiên liệu vượt trội. Với mức tiêu thụ chỉ khoảng 1,47 lít/100 km, mẫu xe này đã kế thừa những ưu điểm nổi bật từ động cơ 125cc danh tiếng của Honda. Điều này không chỉ giúp giảm chi phí vận hành mà còn góp phần bảo vệ môi trường, khiến <b>Future 125 fi</b> trở thành sự lựa chọn hàng đầu cho những ai yêu thích sự tiết kiệm và hiệu quả.</p>\n<h2>3. Những tiện ích được trang bị trên dòng xe fu</h2>\n<p><b>Honda future</b> không chỉ nổi bật với thiết kế hiện đại mà còn được trang bị nhiều tiện ích thông minh, mang lại sự tiện lợi và an toàn cho người sử dụng.</p>\n<p>Hệ thống đèn chiếu sáng tự động</p>\n<p>Một trong những tính năng đáng chú ý của<b> xe future</b> là hệ thống đèn chiếu sáng phía trước luôn tự động bật khi xe hoạt động. Điều này không chỉ giúp người lái có tầm nhìn rõ ràng trong các điều kiện ánh sáng yếu, mà còn giảm thiểu nguy cơ quên bật đèn khi di chuyển. Nhờ đó, khả năng nhận diện của xe trên đường phố được nâng cao, giúp các phương tiện khác dễ dàng quan sát và tránh va chạm.</p>\n\n<p>Ổ khóa đa năng 4 trong 1</p>\n<p><b>Xe future</b> được trang bị ổ khóa đa năng 4 trong 1, bao gồm khóa điện, khóa từ, khóa cổ và khóa yên. Thiết kế này không chỉ mang lại sự thuận tiện trong việc sử dụng mà còn đảm bảo an toàn tối đa cho tài sản của bạn. Chất liệu chống rỉ sét cũng giúp ổ khóa bền bỉ hơn theo thời gian.</p>\n\n<p>Hộc đựng đồ rộng rãi</p>\n<p>Một điểm cộng nữa của dòng <b>xe fu</b> là hộc đựng đồ lớn, có khả năng chứa vừa một mũ bảo hiểm cả đầu cùng với các vật dụng cá nhân khác. Thiết kế thông minh này giúp người dùng dễ dàng mang theo những đồ cần thiết mà không lo lắng về việc thiếu không gian.</p>\n\n<p>Với những tiện ích vượt trội như vậy, <b>mua xe future</b> thực sự là lựa chọn lý tưởng cho những ai đang tìm kiếm một phương tiện di chuyển an toàn và tiện lợi.</p>\n<h2>4. Nên mua xe Future giá tốt ở đâu?</h2>\n<p>Hiện tại,<b> giá xe future</b> đang có sự chênh lệch đáng kể giữa các cửa hàng và khu vực. Để đảm bảo mua được sản phẩm chất lượng và chính hãng, khách hàng nên lựa chọn những địa chỉ uy tín, đặc biệt là các cửa hàng Honda có nhiều năm kinh nghiệm trong ngành.</p>\n<p><strong>Giá xe future</strong> phiên bản tiêu chuẩn: 33.800.000đ&nbsp;</p>\n<p><strong>Giá xe future</strong> phiên bản cao cấp: 36.300.000đ</p>\n<p><strong>Giá xe future</strong> phiên bản đặc biệt: 36.300.000đ</p>\n\n<p>Hệ thống xe máy Hùng Phát tự hào là một trong những địa chỉ <a href=\"/xe-may\"><strong>mua xe máy</strong></a> được nhiều khách hàng tin cậy. Chúng tôi cam kết mang đến cho quý khách hàng dịch vụ và sản phẩm tốt nhất trên thị trường. Nếu bạn đang tìm kiếm một cửa hàng có giá<b> xe fu</b> hợp lý, hãy liên hệ ngay với chúng tôi để nhận được những ưu đãi hấp dẫn!</p>\n<p>Đặc biệt, khi <b>mua xe future</b> tại Hùng Phát trong hôm nay, quý khách sẽ nhận được nhiều lợi ích vượt trội:</p>\n<p>– Hỗ trợ mua xe trả góp với lãi suất cực kỳ ưu đãi.</p>\n<p>– Chỉ cần trả trước từ 10% để rước xe về ngay.</p>\n<p>– Giao xe tận nhà miễn phí.</p>\n<p>– Tặng ngay combo quà tặng độc quyền trị giá lên đến 2.350.000đ.</p>\n<p>– Chương trình thu xe cũ đổi xe mới, giúp bạn tiết kiệm chi phí.</p>\n<p>– Bảo hành chính hãng đảm bảo quyền lợi cho khách hàng.</p>\n<p>Đừng bỏ lỡ cơ hội sở hữu chiếc xe <b>honda future</b> chất lượng với giá cả phải chăng! Hãy đến ngay Hùng Phát hoặc liên hệ qua hotline để được hỗ trợ và tư vấn <a href=\"/xe-may?nhom=honda\"><strong>giá xe honda</strong></a> nhanh chóng.</p>\n<p><strong>HỆ THỐNG XE MÁY HÙNG PHÁT&nbsp;</strong></p>', 1);
