INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-sh-125i', 'Xe Sh 125i', 'honda', '[]', 76800000, 86300000, '/sites/hungphat/img/2024/11/sh-125-phien-ban-the-thao-mau-do-den.webp', '[\"/sites/hungphat/img/2024/11/sh-125-phien-ban-the-thao-mau-do-den.webp\"]', '[\"Đen\",\"Đỏ Đen\",\"Trắng Đen\",\"Xám Đen\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/sh-125-phien-ban-tieu-chuan-mau-den.webp\",\"price\":76800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Trắng Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/sh-125-phien-ban-tieu-chuan-mau-trang-den.webp\",\"price\":76800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Trắng Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/sh-125-phien-ban-cao-cap-mau-trang-den.webp\",\"price\":84800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/sh-125-phien-ban-cao-cap-mau-do-den.webp\",\"price\":84800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/sh-125-phien-ban-dac-biet-mau-den.webp\",\"price\":84800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao\"},{\"name\":\"Màu sắc\",\"value\":\"Xám Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/sh-125-phien-ban-the-thao-mau-xam-den.webp\",\"price\":86300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/sh-125-phien-ban-the-thao-mau-do-den.webp\",\"price\":86300000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Dung tích bình xăng\",\"value\":\"7 lít\"},{\"label\":\"Loại động cơ\",\"value\":\"PGM-FI, xăng, 4 kỳ, 1 xy-lanh, làm mát bằng dung dịch\"},{\"label\":\"Công suất tối đa\",\"value\":\"9,6kW/8.250 vòng/phút\"},{\"label\":\"Dung tích nhớt máy\",\"value\":\"0,9 lít khi rã máy 0,8 lít khi thay nhớt\"},{\"label\":\"Loại truyền động\",\"value\":\"Vô cấp, điều khiển tự động\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Moment cực đại\",\"value\":\"11,9N.m/6.500 vòng/phút\"},{\"label\":\"Dung tích xy-lanh\",\"value\":\"124,8cm³\"},{\"label\":\"Đường kính x Hành trình pít tông\",\"value\":\"53,5mm x 55,5mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"11,5:1\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Kích cỡ lốp trước/ sau\",\"value\":\"Kích cỡ lốp trước: 100/80 - 16 M/C 50P Kích cỡ lốp sau: 120/80 - 16 M/C 60P\"},{\"label\":\"Phuộc trước\",\"value\":\"Ống lồng, giảm chấn thủy lực\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ, giảm chấn thủy lực\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Khối lượng bản thân\",\"value\":\"133kg\"},{\"label\":\"Dài x Rộng x Cao\",\"value\":\"2.090mm x 739mm x 1.129mm\"},{\"label\":\"Khoảng cách trục bánh xe\",\"value\":\"1.353mm\"},{\"label\":\"Độ cao yên\",\"value\":\"799mm\"},{\"label\":\"Khoảng sáng gầm xe\",\"value\":\"146mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000km (tùy điều kiện nào đến trước)\"}]}]', '<p>Xe sh 125i đã chinh phục được lòng tin của người tiêu dùng và trở thành lựa chọn hàng đầu cho những ai yêu thích sự tiện lợi và an toàn khi di chuyển.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ SH 125I HONDA ƯU ĐÃI MỚI NHẤT TRÊN THỊ TRƯỜNG</h2>\n<p>Nhằm đáp ứng nhu cầu của khách hàng, Honda đã không ngừng đổi mới và cho ra mắt nhiều dòng xe tay ga cao cấp. Một trong những sản phẩm tiêu biểu cho sự đổi mới này chính là mẫu <b>xe sh 125i</b>. Với thiết kế ngoại hình sang trọng, thanh lịch cùng với động cơ mạnh mẽ, <b>honda sh 125i </b>thực sự là biểu tượng của đẳng cấp và công nghệ tiên tiến.</p>\n\n<p>Kể từ khi ra mắt, <b>sh 125i</b> đã nhanh chóng chinh phục trái tim của đông đảo người tiêu dùng Việt Nam. Để hiểu rõ hơn về dòng xe <b>sh 125</b> cũng như <b>giá sh 125i</b> mới nhất trên thị trường hiện nay, hãy cùng hệ thống xe máy Hùng Phát khám phá ngay chi tiết trong bài viết dưới đây.</p>\n<h2>1. Giới thiệu về tổng quan thiết kế của xe SH 125i</h2>\n<p>Trong phiên bản mới nhất của dòng <b>xe sh 125i</b>, Honda đã tiếp tục khẳng định vị thế của mình trong phân khúc xe ga cao cấp. Đây không chỉ là một sản phẩm kế thừa những giá trị thiết kế sang trọng và thanh lịch từ các thế hệ trước, mà còn là sự cải tiến vượt bậc, mang đến một diện mạo tinh tế và hiện đại hơn bao giờ hết.</p>\n<p><b>Xe sh 125i </b>được xem là biểu tượng của sự sang trọng và phong cách thời trang hiện đại trong dòng xe ga cao cấp của Honda. Với những đường nét uốn lượn mềm mại, kết hợp cùng các chi tiết tinh xảo, mẫu xe này tạo nên một vẻ đẹp cuốn hút, không chỉ thu hút ánh nhìn mà còn thể hiện được gu thẩm mỹ tinh tế của người sở hữu. Những đường viền sáng bóng trên <b>sh 125</b> không chỉ làm nổi bật thiết kế mà còn giúp xe giữ được vẻ đẹp bền bỉ theo thời gian.</p>\n\n<p>Một trong những điểm nhấn đáng chú ý nhất trên <b>honda sh 125i</b> chính là cụm đèn pha full LED. Được thiết kế thông minh và tối ưu hóa khả năng chiếu sáng, cụm đèn này không chỉ mang lại ánh sáng mạnh mẽ mà còn đảm bảo an toàn cho người lái trong điều kiện ánh sáng yếu hoặc ban đêm. Điều này giúp tăng cường khả năng quan sát và giảm thiểu rủi ro khi di chuyển.</p>\n<p>Mặt đồng hồ của <b>xe sh 125i </b>cũng được nâng cấp với thiết kế thông minh, cho phép hiển thị tốc độ tách rời với các thông số khác. Điều này mang lại trải nghiệm lái xe tối ưu hơn cho người dùng, giúp họ dễ dàng theo dõi tình trạng vận hành của xe mà không bị phân tâm.</p>\n<p><b>Sh 125</b> không chỉ đơn thuần là một phương tiện di chuyển mà còn là biểu tượng của phong cách sống hiện đại. Với thiết kế ấn tượng cùng tính năng vượt trội, mẫu xe này chắc chắn sẽ làm hài lòng cả những khách hàng khó tính nhất.</p>\n<h2>2. Những điểm nổi bật về tiện ích của Honda SH 125i&nbsp;</h2>\n<p>Với nhiều tính năng nổi bật, <b>xe sh 125i </b>đã chinh phục được lòng tin của người tiêu dùng và trở thành lựa chọn hàng đầu cho những ai yêu thích sự tiện lợi và an toàn khi di chuyển.</p>\n<p>Hệ thống kiểm soát lực kéo (HSTC) được trang bị trên phiên bản <b>sh 125i abs</b></p>\n<p><b>Sh 125i abs</b> hiện tại bao gồm 3 phiên bản: cao cấp, đặc biệt và thể thao. Một trong những điểm nhấn đáng chú ý của <b>sh 125i abs</b> chính là hệ thống kiểm soát lực kéo HSTC. Hệ thống này hoạt động dựa trên cảm biến tốc độ quay ở bánh trước và bánh sau, từ đó tính toán độ trượt của bánh sau.&nbsp;</p>\n\n<p>Khi phát hiện tình trạng trượt, hệ thống sẽ tự động điều chỉnh lượng mô-men xoắn của động cơ, giúp người lái dễ dàng kiểm soát xe trong các tình huống khó khăn như tăng ga trên mặt đường trơn trượt. Chức năng này không chỉ mang lại cảm giác an toàn mà còn giúp người điều khiển tự tin hơn khi tham gia giao thông.&nbsp;</p>\n<p><em>Hệ thống chống bó cứng phanh ABS&nbsp;</em></p>\n<p>Được trang bị trên cả hai bánh, hệ thống chống bó cứng phanh ABS là một tính năng quan trọng khác của phiên bản<b> sh 125i abs</b>. Với công nghệ này, người lái có thể phanh gấp mà không lo lắng về việc mất kiểm soát, đặc biệt là khi di chuyển ở tốc độ cao hoặc trên bề mặt đường trơn trượt. Điều này giúp nâng cao khả năng an toàn cho cả người lái và hành khách.</p>\n\n<p><em>Không gian chứa đồ rộng rãi &amp; cổng sạc USB</em></p>\n<p><b>Honda sh 125i </b>được thiết kế với hộc chứa đồ có dung tích lên đến 28L, mang đến không gian rộng rãi để người dùng có thể mang theo nhiều vật dụng cần thiết trong mỗi chuyến đi. Đặc biệt, hộc chứa đồ còn được tích hợp cổng sạc USB tiện lợi, cho phép bạn sạc pin điện thoại hoặc các thiết bị điện tử khác ngay cả khi đang di chuyển.</p>\n<p><em>Thiết kế nắp bình xăng thông minh</em></p>\n<p>Một điểm cộng lớn nữa chính là nắp bình xăng được thiết kế ở phía trước xe. Điều này giúp việc đổ xăng trở nên thuận tiện hơn bao giờ hết; bạn không cần phải mở yên xe mỗi lần cần tiếp nhiên liệu, tiết kiệm thời gian và công sức.</p>\n\n<p>Hệ thống khóa thông minh Smart Key</p>\n<p>Hệ thống khóa thông minh Smart Key là một trong những tính năng hiện đại nhất trên <b>sh 125</b>. Với khả năng xác định vị trí xe từ xa và mở khóa một cách nhanh chóng, hệ thống này không chỉ mang lại sự tiện lợi mà còn tích hợp chức năng báo động chống trộm hiệu quả. Người dùng sẽ hoàn toàn yên tâm khi để chiếc xe của mình ở nơi công cộng.</p>\n\n<p><em>Đèn chiếu sáng luôn sáng</em></p>\n<p>Đèn chiếu sáng phía trước luôn sáng cũng là một điểm nổi bật khác của mẫu xe này. Tính năng này giúp nâng cao khả năng hiện diện của chiếc xe trên đường phố vào ban đêm hoặc trong điều kiện thời tiết xấu, đảm bảo an toàn tối đa cho người lái.</p>\n\n<p><b>Sh 125i abs </b>không chỉ đơn thuần là một phương tiện di chuyển mà còn là sự kết hợp hoàn hảo giữa công nghệ tiên tiến và tiện ích tối ưu dành cho người sử dụng. Với những tính năng nổi bật như hệ thống kiểm soát lực kéo HSTC, phanh ABS an toàn, không gian chứa đồ rộng rãi cùng nhiều tiện ích thông minh khác, mẫu xe này thực sự xứng đáng trở thành lựa chọn hàng đầu cho những ai yêu thích sự sang trọng và an toàn trong từng chuyến đi.</p>\n<h2>3. Động cơ xe mạnh mẽ của SH 125</h2>\n<p><b>Sh 125i </b>nổi bật với khối động cơ125cc eSP tiên tiến, mang lại hiệu suất vận hành vượt trội. Động cơ này không chỉ cung cấp sức mạnh mạnh mẽ, giúp người lái dễ dàng chinh phục mọi cung đường, mà còn đảm bảo sự êm ái trong từng chuyển động.</p>\n<p>Một trong những điểm đáng chú ý của động cơ eSP+ là khả năng tiết kiệm nhiên liệu tối ưu. Nhờ vào công nghệ hiện đại, <b>xe sh 125i</b> giúp giảm thiểu mức tiêu thụ nhiên liệu, từ đó không chỉ tiết kiệm chi phí cho người sử dụng mà còn góp phần bảo vệ môi trường. Sự thân thiện với môi trường của xe máy này là một yếu tố quan trọng trong bối cảnh ngày càng nhiều người quan tâm đến vấn đề bảo vệ hành tinh.</p>\n\n<p>Quý khách hàng đang có nhu cầu tham khảo <b>giá sh 125i </b>vui lòng liên hệ với Hùng Phát để được tư vấn chi tiết. Việc lựa chọn<b> honda sh 125i</b> không chỉ mang lại cho bạn một chiếc xe hiện đại mà còn thể hiện gu thẩm mỹ và sự đẳng cấp. Đây thực sự là sự kết hợp hoàn hảo giữa phong cách thời trang và hiệu suất vượt trội, đáp ứng nhu cầu của những ai yêu thích sự khác biệt và chất lượng trong từng chi tiết. Hãy để<b> sh 125i </b>đồng hành cùng bạn trên mọi nẻo đường!&nbsp;</p>\n<h2>4. Cập nhật giá SH 125i mới nhất trên thị trường hiện nay&nbsp;</h2>\n<p>Hiện nay, <b>giá sh 125i</b> đang được bán tại hệ thống Hùng Phát với mức giá chỉ từ 76 triệu đồng. Đây là một trong những mẫu xe tay ga được yêu thích nhất trên thị trường nhờ thiết kế sang trọng, tính năng vượt trội và độ bền cao.</p>\n\n<p>Đặc biệt, khi quý khách hàng lựa chọn mua xe<b> sh 125</b> tại Hùng Phát, không chỉ nhận được sản phẩm chất lượng mà còn được hưởng nhiều ưu đãi độc quyền hấp dẫn:</p>\n<p>– Dịch vụ tư vấn chuyên nghiệp 24/7: Đội ngũ nhân viên tận tâm của chúng tôi luôn sẵn sàng hỗ trợ và tư vấn cho quý khách mọi lúc, mọi nơi. Quý khách có thể liên hệ qua Hotline, Zalo, Fanpage Facebook hoặc trực tiếp tại ba chi nhánh cửa hàng của chúng tôi để nhận được sự hỗ trợ nhanh chóng và hiệu quả.</p>\n<p>– Chương trình hỗ trợ mua xe trả góp: Chúng tôi hiểu rằng việc sở hữu một chiếc <a href=\"/xe-may\"><b>xe máy</b></a> mới là mong muốn của nhiều người. Vì vậy, Hùng Phát triển khai chương trình hỗ trợ mua xe trả góp với thủ tục đơn giản và lãi suất cực kỳ ưu đãi. Quý khách chỉ cần thanh toán trước từ 10% giá trị xe để có thể rước ngay chiếc <b>sh 125i</b> về nhà.</p>\n<p>– Chương trình thu xe cũ đổi xe mới: Để giúp quý khách dễ dàng nâng cấp lên đời xe mới, chúng tôi cung cấp dịch vụ thu mua xe cũ với quy trình nhanh chóng và thuận tiện.</p>\n<p>– Dịch vụ giao xe tận nơi: Nhằm mang lại sự tiện lợi tối đa cho khách hàng, Hùng Phát cung cấp dịch vụ giao xe tận nhà. Quý khách sẽ không cần phải lo lắng về việc di chuyển đến cửa hàng để nhận xe.</p>\n<p>– Quà tặng độc quyền hấp dẫn: Khi <a href=\"/xe-may\"><b>mua xe honda</b></a> tại Hùng Phát, quý khách sẽ nhận ngay combo quà tặng trị giá lên tới 2.350.000 đồng. Ngoài ra, còn rất nhiều chương trình khuyến mãi khác đang chờ đón quý khách.</p>\n<p>Để biết thêm thông tin chi tiết về <b>giá sh 125i </b>hoặc nhận tư vấn miễn phí, xin vui lòng liên hệ hotline, chúng tôi luôn sẵn sàng phục vụ quý khách!</p>\n<p><strong>HỆ THỐNG XE MÁY HÙNG PHÁT&nbsp;</strong></p>', 1);
