INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-sh-350i', 'Xe Sh 350i', 'honda', '[]', 150300000, 152300000, '/sites/hungphat/img/2024/11/sh-350i-phien-ban-the-thao-mau-xanh-den.webp', '[\"/sites/hungphat/img/2024/11/sh-350i-phien-ban-the-thao-mau-xanh-den.webp\"]', '[\"Trắng Đen\",\"Xám đậm Đen\",\"Xám Đen\",\"Xanh lá Đen\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Trắng Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/sh-350i-phien-ban-dac-biet-mau-trang-den.webp\",\"price\":150300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Xám đậm Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/sh-350i-phien-ban-dac-biet-mau-xam-dam-den.webp\",\"price\":150300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh lá Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/sh-350i-phien-ban-the-thao-mau-xanh-den.webp\",\"price\":150300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao\"},{\"name\":\"Màu sắc\",\"value\":\"Xám Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/sh-350i-phien-ban-the-thao-mau-xam-den.webp\",\"price\":152300000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Dung tích bình xăng\",\"value\":\"9,3 lít\"},{\"label\":\"Loại động cơ\",\"value\":\"Xăng 4 kỳ, 1 xi lanh, làm mát chất lỏng\"},{\"label\":\"Công suất tối đa\",\"value\":\"21,5 kW/7.500 vòng/phút\"},{\"label\":\"Dung tích nhớt máy\",\"value\":\"Sau khi xả: 1,4 lít Sau khi xả và thay lưới lọc: 1,5 lít Sau khi rã máy: 1,85 lít\"},{\"label\":\"Mức tiêu thụ nhiên liệu\",\"value\":\"3,52 lít/100km\"},{\"label\":\"Loại truyền động\",\"value\":\"Biến thiên vô cấp\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Moment cực đại\",\"value\":\"31,8 Nm/5.250 vòng/phút\"},{\"label\":\"Dung tích xy-lanh\",\"value\":\"330 cm3\"},{\"label\":\"Đường kính x Hành trình pít tông\",\"value\":\"77 mm x 70,77 mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"10,5:1\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Kích cỡ lốp trước/ sau\",\"value\":\"Trước: 110/70-16 M/C 52S Sau: 130/70R16 M/C 61S\"},{\"label\":\"Phuộc trước\",\"value\":\"Phuộc ống lồng giảm chấn thủy lực\"},{\"label\":\"Phuộc sau\",\"value\":\"Phuộc sau đôi, lò xo trụ, giảm chấn thủy lực\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Khối lượng bản thân\",\"value\":\"172 kg\"},{\"label\":\"Dài x Rộng x Cao\",\"value\":\"2.160 mm x 743 mm x 1.161 mm\"},{\"label\":\"Khoảng cách trục bánh xe\",\"value\":\"1.450 mm\"},{\"label\":\"Độ cao yên\",\"value\":\"805 mm\"},{\"label\":\"Khoảng sáng gầm xe\",\"value\":\"132 mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000km (tùy điều kiện nào đến trước)\"}]}]', '<p>Mẫu xe sh 350i mới không chỉ kế thừa những giá trị truyền thống đó mà còn được cải tiến với thiết kế thể thao, tối giản nhưng vẫn giữ được vẻ hiện đại và thanh lịch.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>CẬP NHẬT GIÁ SH 350I MỚI NHẤT CỦA HONDA&nbsp;</h2>\n<p>Tại Việt Nam, xe máy <b>sh 350</b> đã từ lâu trở thành biểu tượng cho sự đẳng cấp và sang trọng. Mẫu <b>xe sh 350i</b> mới không chỉ kế thừa những giá trị truyền thống đó mà còn được cải tiến với thiết kế thể thao, tối giản nhưng vẫn giữ được vẻ hiện đại và thanh lịch.</p>\n<p>Với việc trang bị công nghệ tiên tiến, <b>honda sh 350i</b> không chỉ mang đến sức mạnh vượt trội và khả năng vận hành ấn tượng mà còn thể hiện sự tinh tế và phong cách của người sở hữu. Dưới đây là <b>giá sh 350i </b>mới nhất hiện nay tại Hùng Phát.</p>\n\n<h2>1. Giới thiệu về những điểm nổi bật trong thiết kế của xe sh 350i mới</h2>\n<p><em>Thiết kế châu âu sang trọng và thể thao</em></p>\n<p><b>Xe sh 350i </b>không chỉ là một chiếc xe máy, mà còn là biểu tượng của sự hiện đại và phong cách. Với dáng vẻ bề thế, mẫu xe này thu hút ánh nhìn ngay từ cái nhìn đầu tiên. Logo SH được mạ crôm tối màu không chỉ tạo điểm nhấn mà còn thể hiện sự sang trọng, khẳng định đẳng cấp của sản phẩm.</p>\n\n<p><em>Mặt nạ trước đột phá</em></p>\n<p>Mặt nạ phía trước của <b>honda sh 350i</b> được thiết kế hoàn toàn mới, mang đậm dấu ấn của những mẫu xe phân khối lớn. Họa tiết chấm tròn trên mặt nạ không chỉ tạo nên vẻ thể thao mà còn làm nổi bật tính năng động của chiếc xe. Hệ thống đèn LED hiện đại được áp dụng cho toàn bộ các bộ phận chiếu sáng, mang lại ánh sáng mạnh mẽ và hình ảnh cao cấp.</p>\n<p><em>Đèn chiếu sáng tinh tế</em></p>\n<p>Đèn chiếu sáng phía trước hoàn toàn mới kết hợp cùng hai đèn xi nhan được thiết kế sắc nét, góp phần tôn vinh phong cách thể thao và hiện đại của<b> sh 350i</b>. Điều này không chỉ giúp tăng cường khả năng chiếu sáng mà còn nâng cao tính thẩm mỹ cho tổng thể thiết kế.</p>\n<p><em>Màu sắc thời thượng</em></p>\n<p>Phiên bản thể thao mới nhất của <b>sh 350</b> bổ sung sắc xanh thời thượng, lấy cảm hứng từ những mẫu xe phân khối lớn nổi tiếng của Honda. Màu sắc này không chỉ làm nổi bật chiếc xe mà còn mang đến sự cuốn hút đầy lôi cuốn cho người sử dụng.</p>\n\n<p><em>Thiết kế phía sau cuốn hút</em></p>\n<p>Cụm đèn hậu LED được trang trí với họa tiết tổ ong vừa thể thao vừa tinh tế, tạo nên một cái nhìn hấp dẫn từ phía sau. Thiết kế này không chỉ đẹp mắt mà còn đảm bảo hiệu suất chiếu sáng tốt nhất.</p>\n<p><em>Mặt đồng hồ LCD hiện đại</em></p>\n<p>Mặt đồng hồ LCD trên <b>sh 350 </b>được thiết kế mạnh mẽ và hiện đại, hiển thị rõ ràng tất cả các thông số cần thiết cùng với các đèn báo hoạt động. Điều này giúp người lái dễ dàng theo dõi tình trạng xe trong quá trình di chuyển, nâng cao trải nghiệm lái xe an toàn và tiện lợi hơn.</p>\n\n<p><b>Xe sh 350i</b> không chỉ đơn thuần là một phương tiện di chuyển; nó là sự kết hợp hoàn hảo giữa thiết kế sang trọng và công nghệ tiên tiến, đáp ứng nhu cầu ngày càng cao của người tiêu dùng hiện đại.</p>\n<h2>2. Giới thiệu về động cơ xe honda sh 350i</h2>\n<p><b>Sh 350i mới </b>được trang bị động cơ eSP+ thế hệ mới, một bước tiến vượt bậc trong công nghệ động cơ xe máy. Với dung tích 330cc, động cơ này hoạt động theo chu trình 4 kỳ, sử dụng một xy lanh và được làm mát bằng chất lỏng. Đặc biệt, hệ thống phun xăng điện tử PGC-FI giúp tối ưu hóa quá trình đốt cháy nhiên liệu, từ đó nâng cao hiệu suất vận hành.</p>\n<p>Động cơ eSP+ không chỉ mang lại công suất vượt trội mà còn giảm thiểu ma sát và rung lắc, tạo cảm giác lái êm ái và thoải mái cho người sử dụng. Nhờ vào việc áp dụng các công nghệ tiên tiến, <b>sh 350</b> đạt tiêu chuẩn khí thải Euro 4*, góp phần bảo vệ môi trường và tiết kiệm nhiên liệu hiệu quả.</p>\n\n<p>Với sự kết hợp hoàn hảo giữa sức mạnh và tính năng thân thiện với môi trường, động cơ eSP+ của <b>xe sh 350i</b> không chỉ đáp ứng nhu cầu di chuyển hàng ngày mà còn mang đến trải nghiệm lái xe đẳng cấp cho mọi tín đồ yêu thích sự sang trọng và hiện đại.</p>\n<h2>3. Giới thiệu về công nghệ và tiện ích của xe sh 350</h2>\n<p><em>Hệ thống chống bó cứng phanh (ABS) 2 kênh trên SH 350</em></p>\n<p><b>Xe sh 350i</b> được trang bị hệ thống chống bó cứng phanh (ABS) 2 kênh, hoạt động hiệu quả trên cả bánh trước và bánh sau. Hệ thống này giúp phân bổ lực phanh một cách hợp lý, đảm bảo xe luôn duy trì trạng thái cân bằng ổn định. Điều này đặc biệt quan trọng trong các tình huống phanh gấp ở tốc độ cao hoặc khi di chuyển trên những đoạn đường trơn trượt, giúp người lái tự tin hơn trong mọi điều kiện.</p>\n<p><em>Hộc đựng đồ phía trước tiện lợi</em></p>\n<p>Hộc đựng đồ phía trước của<b> sh 350i mới</b> có dung tích lớn hơn và được thiết kế với lẫy đóng/mở thuận tiện. Người dùng có thể dễ dàng để điện thoại cầm tay cùng các vật dụng nhỏ gọn khác vào đây. Ngoài ra, cổng sạc USB loại C cũng được trang bị để đáp ứng nhu cầu sạc pin điện thoại khi cần thiết.</p>\n\n<p><em>Hệ thống kiểm soát lực kéo (HSTC)</em></p>\n<p><b>Honda sh 350i </b>còn được trang bị hệ thống kiểm soát lực kéo HSTC, mang lại khả năng vận hành mượt mà và an toàn. HSTC giúp kiểm soát độ bám đường của bánh sau trên các bề mặt trơn trượt, từ đó cải thiện khả năng tăng tốc và cảm giác lái cho người điều khiển. Chức năng này có thể dễ dàng được kích hoạt hoặc tắt thông qua công tắc trên tay lái bên trái. Khi hệ thống HSTC hoạt động, đèn báo hiệu chữ “T” sẽ sáng lên trên màn hình điện tử của xe, giúp người lái nắm bắt tình trạng bám đường một cách nhanh chóng.</p>\n<p><em>Kết nối điện thoại qua Bluetooth</em></p>\n<p><b>Sh 350</b> tích hợp công nghệ kết nối Bluetooth với điện thoại thông minh thông qua ứng dụng My Honda+. Tính năng này cho phép người dùng theo dõi toàn bộ thông tin liên quan đến xe như tình trạng vận hành, lịch sử sửa chữa và bảo dưỡng, mức tiêu hao nhiên liệu cũng như các sự kiện mới nhất từ Honda Việt Nam.</p>\n<p><em>Hộc đựng đồ dưới yên rộng rãi với đèn soi</em></p>\n<p>Với hộc đựng đồ dưới yên có dung tích lớn, <b>sh 350i mới</b> có thể chứa vừa một mũ bảo hiểm cả đầu cùng nhiều vật dụng khác. Đặc biệt, hộc đồ còn được trang bị đèn soi giúp người dùng dễ dàng tìm kiếm đồ vật trong điều kiện thiếu sáng. Bình xăng của xe cũng có dung tích lớn lên tới 9.3 lít, đáp ứng nhu cầu di chuyển xa mà không cần dừng lại thường xuyên.</p>\n<p><em>Hệ thống khóa thông minh</em></p>\n<p><b>Xe sh 350i</b> sở hữu hệ thống khóa thông minh hiện đại, cho phép xác định vị trí xe và mở khóa từ xa một cách tiện lợi. Thiết kế sang trọng cùng công nghệ tiên tiến không chỉ tối ưu hóa khả năng chống trộm mà còn đi kèm với còi báo động để tăng cường an ninh cho phương tiện.</p>\n\n<p><em>Đèn chiếu sáng phía trước luôn sáng &amp; tín hiệu dừng khẩn cấp</em></p>\n<p>Chế độ đèn chiếu sáng luôn bật giúp người lái duy trì tầm nhìn tốt nhất trong mọi điều kiện ánh sáng và giảm thiểu nguy cơ quên bật đèn khi di chuyển vào ban đêm hoặc trong điều kiện thiếu sáng. Đặc biệt, tính năng tự động bật sáng của đèn xi nhan khi phanh gấp sẽ cảnh báo kịp thời cho các phương tiện phía sau, góp phần nâng cao an toàn giao thông.</p>\n<p>Với những tính năng vượt trội này, <b>honda sh 350i</b> không chỉ là một phương tiện di chuyển mà còn là biểu tượng của sự an toàn và tiện nghi cho người sử dụng.</p>\n<h2>4. Giá SH 350i mới nhất tại Hệ thống xe máy Hùng Phát</h2>\n<p>Xe máy SH 350i luôn là một trong những mẫu xe được yêu thích nhất trên thị trường Việt Nam.Tại <a href=\"/xe-may\"><strong>đại lý xe máy</strong></a> Hùng Phát, chúng tôi tự hào mang đến cho khách hàng thông tin mới nhất về <b>giá sh 350i</b> cũng như các chương trình khuyến mãi hấp dẫn liên quan đến mẫu xe này.</p>\n\n<p>Hiện tại, <b>giá sh 350i </b>tại hệ thống của chúng tôi dao động từ khoảng 150 triệu đồng tùy thuộc vào từng phiên bản và màu sắc. Đặc biệt, với chính sách hỗ trợ tài chính linh hoạt, khách hàng có thể dễ dàng sở hữu chiếc xe mơ ước mà không cần lo lắng về vấn đề tài chính.</p>\n<p><b>Giá sh 350i</b> màu xám thể thao: 151.300.000đ</p>\n<p><b>Giá sh 350i</b> (các màu còn lại): 150.300.000đ</p>\n<p>Ngoài ra, Xe máy Hùng Phát còn cung cấp dịch vụ bảo trì và bảo dưỡng chuyên nghiệp nhằm đảm bảo chiếc xe luôn hoạt động trong tình trạng tốt nhất. Đội ngũ kỹ thuật viên giàu kinh nghiệm của chúng tôi sẵn sàng tư vấn và hỗ trợ khách hàng trong việc lựa chọn phụ kiện cũng như các gói dịch vụ phù hợp.</p>\n<p>Chúng tôi cam kết mang đến cho khách hàng những trải nghiệm mua sắm tuyệt vời nhất với dịch vụ tận tâm và sản phẩm chất lượng cao. Nếu bạn đang tìm kiếm một <a href=\"/xe-may?nhom=honda\"><strong>đại lý honda</strong></a> uy tín, hãy đến ngay Hệ thống Hùng Phát để trải nghiệm và sở hữu xe <b>sh 350i mới</b> ngay hôm nay!</p>\n<p><strong>HỆ THỐNG XE MÁY HÙNG PHÁT&nbsp;</strong></p>', 1);
