INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-shark-50cc', 'Xe Shark 50cc', 'sym', '[]', 24900000, 24900000, '/sites/hungphat/img/2024/11/shark-50-mau-xanh-xam-den.webp', '[\"/sites/hungphat/img/2024/11/shark-50-mau-xanh-xam-den.webp\"]', '[\"Đen nhám\",\"Trắng Đen\",\"Xanh dương Đen\",\"Xanh Xám Đen\"]', '[{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Đen nhám\"}],\"img\":\"/sites/hungphat/img/2024/11/shark-50-mau-den-nham.webp\",\"price\":24900000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Trắng Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/shark-50-mau-trang-den.webp\",\"price\":24900000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xanh dương Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/shark-50-mau-xanh-duong-den.webp\",\"price\":24900000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xanh Xám Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/shark-50-mau-xanh-xam-den.webp\",\"price\":24900000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Mức tiêu hao nhiên liệu\",\"value\":\"1.95 lít/100 Km\"},{\"label\":\"Động cơ\",\"value\":\"4 thì\"},{\"label\":\"Hệ thống làm mát máy\",\"value\":\"Bằng không khí\"},{\"label\":\"Công suất tối đa\",\"value\":\"2.45 kw/ 8000 rpm\"},{\"label\":\"Momen cực đại\",\"value\":\"3.1 Nm/ 7000 rpm\"},{\"label\":\"Tốc độ tối đa\",\"value\":\"50 km/h\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Thắng/Phanh trước\",\"value\":\"Đùm (Cơ)\"},{\"label\":\"Thắng/Phanh sau\",\"value\":\"Đùm (Cơ)\"},{\"label\":\"Vỏ/Lốp trước\",\"value\":\"Có ruột 70/90- 14\"},{\"label\":\"Vỏ/Lốp sau\",\"value\":\"Có ruột 80/90- 14\"},{\"label\":\"Đầu đèn (đèn pha)\",\"value\":\"12V - 35/ 35W\"},{\"label\":\"Đèn sau, đèn thắng\",\"value\":\"12V - 5W/18W\"},{\"label\":\"Đèn Signal\",\"value\":\"12V / 10W x 4\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Dài - Rộng - Cao\",\"value\":\"1931 - 665 - 1096 (mm)\"},{\"label\":\"Khoảng cách 2 trục\",\"value\":\"1335 (mm)\"},{\"label\":\"Khoảng cách gầm\",\"value\":\"100 (mm)\"},{\"label\":\"Tổng trọng lượng khô\",\"value\":\"100 kg\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"5 lít\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000km\"}]}]', '<p>Shark 50cc là một trong những mẫu xe tay ga 50cc nổi bật sở hữu thiết kế trẻ trung và hiện đại. Với các phiên bản màu sắc đa dạng, dòng xe sym shark 50 mang đến cho người dùng nhiều lựa chọn.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>MUA XE SYM SHARK 50CC GIÁ RẺ MỚI NHẤT HIỆN NAY</h2>\n<p>Được thiết kế theo xu hướng nhỏ gọn và hiện đại,<b> Shark 50cc</b> không chỉ có đường nét thanh thoát mà còn nhẹ nhàng, giúp người dùng dễ dàng điều khiển và đảm bảo an toàn khi di chuyển. Với sự kết hợp hoàn hảo giữa phong cách và tính năng, <b>xe sym shark 50</b> hứa hẹn sẽ là lựa chọn lý tưởng cho những bạn trẻ năng động. Hãy cùng Hùng Phát khám phá những điểm nổi bật của <b>xe shark 50</b> và <b>giá xe shark 50 </b>qua bài viết dưới đây.</p>\n<h2>1. Giới thiệu về thiết kế đặc của dòng xe Shark 50cc</h2>\n<p><b>Shark 50cc</b> là một trong những mẫu xe tay ga 50cc nổi bật với thiết kế trẻ trung và hiện đại. Với các phiên bản màu sắc đa dạng và bắt mắt, dòng xe <b>sym shark 50</b> mang đến cho người dùng nhiều lựa chọn phong phú, từ màu trắng đen, xám đen, xanh đen cho đến đen nhám. Những gam màu này không chỉ giúp chủ sở hữu nổi bật giữa phố phường mà còn thể hiện phong cách năng động và sáng tạo của thế hệ Gen Z.</p>\n<p>– <b>Shark 50cc</b> phiên bản màu trắng đen: Sự kết hợp hoàn hảo giữa thanh lịch và sang trọng, phiên bản này là lựa chọn lý tưởng cho những ai yêu thích phong cách tối giản nhưng vẫn muốn nổi bật giữa đám đông.</p>\n<p>– <b>Xe shark 50</b> phiên bản màu xám đen: Với vẻ ngoài mạnh mẽ và cá tính, phiên bản này phù hợp cho những người muốn thể hiện phong cách độc đáo và khẳng định bản thân trong mọi tình huống.</p>\n<p>– Dòng <b>xe shark 50cc </b>phiên bản màu xanh đen: Được thiết kế dành riêng cho những tâm hồn trẻ trung và năng động, phiên bản này phản ánh lối sống hiện đại của thế hệ Gen Z, luôn hướng tới sự mới mẻ và sáng tạo.</p>\n<p>– <b>Sym shark 50</b> phiên bản màu đen nhám: Tạo nên một cảm giác bí ẩn và cuốn hút, phiên bản này là sự lựa chọn hoàn hảo cho những ai yêu thích sự khác biệt và muốn nổi bật theo cách riêng của mình.</p>\n<p>Không chỉ dừng lại ở màu sắc, mỗi chi tiết trên <b>shark 50cc</b> đều được thiết kế tỉ mỉ. Từ vị trí logo đến thiết kế đèn signal hay mặt nạ vuốt cong mềm mại đều thể hiện sự chăm chút kỹ lưỡng từ nhà sản xuất. Những yếu tố này kết hợp hài hòa tạo nên một tổng thể hoàn mỹ, vừa hiện đại vừa sang trọng.&nbsp;</p>\n<h2>2. Động cơ xe 50cc tiết kiệm nhiên liệu của SYM Shark 50</h2>\n<p>Hiện nay, việc tiết kiệm nhiên liệu và bảo vệ môi trường ngày càng trở thành ưu tiên hàng đầu của thế hệ Gen Z. Hiểu rõ điều này, Sym đã cho ra mắt mẫu xe <b>sym shark 50</b> với động cơ 50cc được cải tiến vượt trội. Động cơ này không chỉ mang lại khả năng khởi động nhanh chóng mà còn nổi bật với mức tiêu thụ nhiên liệu ấn tượng lên đến 50 km/lít.</p>\n<p>Với thiết kế thân thiện với môi trường, <b>shark 50cc</b> không chỉ giúp người dùng tiết kiệm chi phí xăng dầu mà còn giảm thiểu tác động tiêu cực đến thiên nhiên. Hiệu suất vận hành tối ưu của xe đảm bảo mang lại trải nghiệm lái mượt mà và an toàn cho người sử dụng.</p>\n<p><b>Shark 50</b> chính là lựa chọn hoàn hảo cho những bạn trẻ yêu thích phong cách sống hiện đại, bền vững và có trách nhiệm với môi trường.</p>\n<h2>3. Tính năng và tiện ích nổi bật của xe Shark 50cc</h2>\n<p>Với <b>xe shark 50cc</b>, bạn sẽ trải nghiệm sự thoải mái và tự tin trong suốt hành trình. Thiết kế sàn để chân thông minh giúp giảm thiểu mệt mỏi trong những chuyến đi dài, đồng thời tạo cảm giác thư giãn tối đa. Vị trí nắp bình xăng được bố trí hợp lý ở phía trước, giúp việc đổ xăng trở nên dễ dàng hơn bao giờ hết.&nbsp;</p>\n<p>Đặc biệt, mặc dù có kiểu dáng gọn nhẹ nhưng cốp chứa đồ của <b>xe sym shark 50</b> lại có dung tích lớn, đủ sức chứa hai mũ bảo hiểm cùng nhiều vật dụng cá nhân khác.</p>\n<p>Bên cạnh đó, <b>xe shark 50cc</b> còn được trang bị nhiều tính năng thông minh nhằm đảm bảo an toàn tối đa cho người lái. Gầm xe cao kết hợp với phuộc sau có khả năng tự điều chỉnh nhiều nấc giúp xe vận hành ổn định trên mọi địa hình. Hệ thống đèn lái halogen 35W với độ chiếu sáng mạnh mẽ không chỉ tăng cường tầm nhìn mà còn đảm bảo an toàn khi di chuyển vào ban đêm.</p>\n<p>Đặc biệt dành cho các bạn nữ, việc dựng xe trở nên dễ dàng hơn nhờ vào thiết kế chân chống cải tiến theo nguyên lý đòn bẩy, chỉ cần một lực nhẹ là có thể dựng xe một cách nhanh chóng.&nbsp;</p>\n<p>Bánh xe lớn 14 inches không chỉ tăng cường độ bám đường mà còn cải thiện khả năng kiểm soát và giảm thiểu nguy cơ trượt ngã. Thiết kế bánh mâm mới với dạng 5 cánh kép xoắn cong không chỉ nâng cao lực phản hồi mà còn mang lại cảm giác lái cực kỳ êm ái cùng điểm nhấn thẩm mỹ độc đáo cho chiếc xe.</p>\n<p>Với tất cả những ưu điểm nổi bật này, <b>sym shark 50</b> thực sự là sự lựa chọn hoàn hảo cho những ai đang tìm kiếm một chiếc xe vừa tiện nghi vừa an toàn trong cuộc sống hàng ngày.</p>\n<h2>4. Địa điểm mua xe Shark 50 giá rẻ mới nhất hiện nay</h2>\n<p>Hệ thống xe máy Hùng Phát tự hào là đại lý chính hãng của thương hiệu SYM, mang đến cho quý khách hàng những mẫu <a href=\"/xe-may\"><b>xe máy</b></a> chất lượng và hiện đại nhất trên thị trường. Với uy tín và kinh nghiệm lâu năm, chúng tôi cam kết cung cấp dịch vụ tốt nhất để đáp ứng nhu cầu của khách hàng.</p>\n<p>Khi quý khách hàng lựa chọn mua <b>xe shark 50cc</b> tại Hùng Phát trong hôm nay, bạn sẽ nhận được nhiều ưu đãi hấp dẫn:</p>\n<p>– Tặng thêm 18 tháng kiểm tra xe định kỳ miễn phí sau khi hết thời gian bảo hành, giúp bạn yên tâm hơn trong quá trình sử dụng.</p>\n<p>– Hỗ trợ mua xe trả góp trả trước chỉ với 0Đ, chỉ cần mang theo chứng minh nhân dân hoặc cần CCCD, hồ sơ của bạn sẽ được duyệt nhanh chóng trong vòng 20 phút.</p>\n<p>– Quà tặng độc quyền hấp dẫn: Nhận ngay bộ quà trị giá 2.350.000đ cùng với hàng ngàn chương trình khuyến mãi hấp dẫn khác.</p>\n<p>– Dịch vụ giao xe tận nhà: Chúng tôi cung cấp dịch vụ giao xe tận nơi, giúp bạn tiết kiệm thời gian và công sức khi mua sắm.</p>\n<p>– Dịch vụ tư vấn online tiện lợi: Đội ngũ tư vấn viên của chúng tôi luôn sẵn sàng hỗ trợ tư vấn quý khách hàng 24/7 qua các kênh trực tuyến.</p>\n<p>Hiện<b> giá xe shark 50 </b>mới nhất tại cửa hàng đang là 24.900.000đ, tuỳ theo từng phiên bản và thời điểm mà <b>giá xe shark 50 </b>sẽ có sự thay đổi.</p>\n<p>Đừng bỏ lỡ cơ hội sở hữu chiếc <b>xe shark 50cc</b> chất lượng với nhiều ưu đãi đặc biệt! Hãy liên hệ ngay với <a href=\"/xe-may?nhom=sym\"><b>đại lý sym</b></a> Hùng Phát để tham khảo <b>giá xe shark 50</b> mới nhất. Chúng tôi rất hân hạnh được đồng hành cùng quý khách hàng trên mọi nẻo đường!</p>\n<p><strong>HỆ THỐNG XE MÁY HÙNG PHÁT&nbsp;</strong></p>', 1);
