INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-vario-125-nhap-khau', 'Xe Vario 125 nhập khẩu', 'xe-may-nhap-khau', '[]', 43000000, 45500000, '/sites/hungphat/img/2024/11/vario-125-nhap-khau-smartkey-mau-xanh.webp', '[\"/sites/hungphat/img/2024/11/vario-125-nhap-khau-smartkey-mau-xanh.webp\"]', '[\"Đen\",\"Đỏ\",\"Trắng\",\"Xanh đậm\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Chìa khoá\"},{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/vario-125-nhap-khau-chia-khoa-mau-den.webp\",\"price\":43000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Chìa khoá\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ\"}],\"img\":\"/sites/hungphat/img/2024/11/vario-125-nhap-khau-chia-khoa-mau-do.webp\",\"price\":43000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Smartkey\"},{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/vario-125-nhap-khau-smartkey-mau-den.webp\",\"price\":45500000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Smartkey\"},{\"name\":\"Màu sắc\",\"value\":\"Trắng\"}],\"img\":\"/sites/hungphat/img/2024/11/vario-125-nhap-khau-smartkey-mau-trang.webp\",\"price\":45500000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Smartkey\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh đậm\"}],\"img\":\"/sites/hungphat/img/2024/11/vario-125-nhap-khau-smartkey-mau-xanh.webp\",\"price\":45500000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Loại máy\",\"value\":\"4 bước, SOHC, eSP, Làm mát bằng chất lỏng\"},{\"label\":\"Hệ thống cung cấp nhiên liệu\",\"value\":\"PGM-FI (Phun nhiên liệu theo chương trình)\"},{\"label\":\"Bước âm lượng\",\"value\":\"124,8cc\"},{\"label\":\"Đường kính X Bước\",\"value\":\"52,4 x 57,9mm\"},{\"label\":\"So sánh nén\",\"value\":\"11,0 : 1\"},{\"label\":\"Loại truyền động\",\"value\":\"Otomatis, V-Matic\"},{\"label\":\"Công suất tối đa\",\"value\":\"8,2 kW (11,1 PS) / 8.500 vòng/phút\"},{\"label\":\"Mô-men xoắn tối đa\",\"value\":\"10,8 Nm (1,1 kgf.m) / 5.000 vòng/phút\"},{\"label\":\"Loại khởi động\",\"value\":\"Điện\"},{\"label\":\"Loại ly hợp\",\"value\":\"Ly tâm tự động, loại khô\"},{\"label\":\"Loại dầu bôi trơn\",\"value\":\"0,8 lít (Thay thế định kỳ)\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"5,5 lít\"},{\"label\":\"Dung tích dầu bôi trơn\",\"value\":\"0,8 lít khi thay thế định kỳ\"},{\"label\":\"Công suất hộp chữ U\",\"value\":\"18 lít\"},{\"label\":\"Loại pin hoặc Aki\",\"value\":\"MF 12V-5Ah\"},{\"label\":\"Hệ thống đánh lửa\",\"value\":\"Transisterized đầy đủ\"},{\"label\":\"Loại bugi\",\"value\":\"NGK CPR9EA-9 / Denso U27EPR9\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Loại khung\",\"value\":\"Xương dưới\"},{\"label\":\"Hệ thống giảm xóc trước/sau\",\"value\":\"Telescopi/Swingarm\"},{\"label\":\"Kích thước lốp trước\",\"value\":\"90/80 – 14M/C 43 P Không săm\"},{\"label\":\"Kích thước lốp sau\",\"value\":\"100/80 - 14M/C 48P Không săm\"},{\"label\":\"Phanh trước\",\"value\":\"Phanh đĩa lượn sóng\"},{\"label\":\"Phanh sau\",\"value\":\"Phanh đùm\"},{\"label\":\"Hệ thống phanh\",\"value\":\"Hệ thống phanh kết hợp (CBS)\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Dài x rộng x cao\",\"value\":\"1.918 x 679 x 1.066mm\"},{\"label\":\"Chiều cao ghế\",\"value\":\"769mm\"},{\"label\":\"Chiều dài cơ sở\",\"value\":\"1.280mm\"},{\"label\":\"Khoảng cách thấp nhất tới mặt đất\",\"value\":\"131mm\"},{\"label\":\"Trọng lượng lề đường\",\"value\":\"111kg\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"18 tháng kiểm tra định kỳ\"}]}]', '<p>Việc sở hữu vario 125 nhập khẩu không chỉ đáp ứng nhu cầu di chuyển hàng ngày mà còn mang đến trải nghiệm lái xe an toàn, tiện lợi và đầy phong cách. Hãy để chiếc xe này đồng hành cùng bạn trên mọi nẻo đường!</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>MUA XE VARIO 125 NHẬP KHẨU GIÁ RẺ</h2>\n<p>Phiên bản mới của <b>xe vario 125 nhập khẩu</b> vừa chính thức ra mắt đã nhanh chóng thu hút sự quan tâm mạnh mẽ từ cả người tiêu dùng lẫn giới chuyên môn. Với những cải tiến đáng kể và tích hợp nhiều tính năng hiện đại, <b>vario 125 nhập khẩu</b> hứa hẹn mang đến cho người lái những trải nghiệm thú vị và tuyệt vời.</p>\n<p>Không chỉ nổi bật với các tính năng ưu việt, <b>honda vario 125 nhập</b> còn được đánh giá cao nhờ mức giá cạnh tranh, đáp ứng tốt nhu cầu của đa số người dùng hiện nay. Chính điều này đã giúp mẫu xe trở thành lựa chọn hàng đầu trong phân khúc xe tay ga nhập khẩu tại thị trường Việt Nam.</p>\n<p>Hãy cùng hệ thống xe máy Hùng Phát khám phá chi tiết những điểm nổi bật của <b>xe vario 125 nhập khẩu</b> và tìm hiểu địa chỉ mua xe uy tín với giá cả phải chăng qua bài viết dưới đây.</p>\n<h2>1. Thiết kế của xe Vario 125 nhập khẩu</h2>\n<p>Phiên bản mới của <b>xe vario 125 nhập khẩu</b> không chỉ gây ấn tượng bởi những cải tiến kỹ thuật vượt trội mà còn thu hút người tiêu dùng nhờ vào sự đa dạng trong thiết kế màu sắc và phiên bản. <b>Vario 125 nhập</b> không chỉ đơn thuần là một phương tiện di chuyển, mà còn là biểu tượng thể hiện phong cách sống và cá tính riêng biệt của mỗi người.</p>\n<p>Với nhiều lựa chọn màu sắc phong phú, từ những tông màu cổ điển thanh lịch đến những gam màu hiện đại nổi bật, <b>honda vario 125 nhập</b> cho phép khách hàng tự do thể hiện gu thẩm mỹ và cá tính của mình. Dù bạn là người yêu thích sự tinh tế, năng động hay muốn khẳng định bản thân với những sắc thái nổi bật, phiên bản mới của Vario luôn đáp ứng được mọi nhu cầu.</p>\n<p>Mỗi chi tiết trên xe <b>vario 125 nhập</b> đều được chăm chút tỉ mỉ, từ thiết kế ngoại thất đến các tính năng bên trong. Điều này không chỉ mang lại trải nghiệm lái xe thoải mái mà còn tạo nên một sản phẩm mang đậm dấu ấn cá nhân. Mua <b>xe vario 125 nhập khẩu </b>không chỉ đơn thuần là sở hữu một phương tiện giao thông; đó còn là việc đầu tư vào một biểu tượng của sự sang trọng và phong cách sống hiện đại.</p>\n<p>Với sự kết hợp hoàn hảo giữa thiết kế thời trang và công nghệ tiên tiến, <b>vario 125 nhập khẩu</b> chắc chắn sẽ làm hài lòng cả những khách hàng khó tính nhất. Hãy để chiếc xe này đồng hành cùng bạn trên mọi nẻo đường, khẳng định phong cách và cá tính riêng biệt của chính mình!</p>\n<h2>2. Khám phá tính năng và tiện ích của Honda Vario 125 nhập</h2>\n<p><b>Xe vario 125 nhập khẩu </b>không chỉ là một phương tiện di chuyển, mà còn là biểu tượng của sự sang trọng và tiện nghi. Với thiết kế hiện đại và các tính năng tiên tiến, chiếc xe này hứa hẹn mang đến trải nghiệm lái xe tuyệt vời cho người sử dụng.</p>\n<p><em>Hệ thống đèn chiếu sáng full LED</em></p>\n<p>Một trong những điểm nổi bật của <b>honda vario 125 nhập</b> chính là hệ thống đèn trước Full LED. Với công nghệ chiếu sáng tiên tiến, đèn LED không chỉ cung cấp ánh sáng mạnh mẽ, giúp người lái dễ dàng quan sát trong điều kiện thiếu sáng, mà còn tạo nên vẻ ngoài tinh tế và hiện đại cho xe. Đèn sau sử dụng công nghệ LED kép cũng góp phần nâng cao tính thẩm mỹ và an toàn khi di chuyển vào ban đêm.</p>\n<p><em>Lốp xe rộng hơn</em></p>\n<p>Với lốp xe được thiết kế rộng hơn, <b>Vario 125&nbsp; nhập </b>mang lại cảm giác ổn định và thoải mái hơn khi vận hành. Lốp rộng không chỉ tăng cường độ bám đường mà còn giảm thiểu nguy cơ trượt ngã, giúp người lái tự tin hơn trên mọi cung đường.</p>\n<p><em>Bảng đồng hồ kỹ thuật số LCD</em></p>\n<p>Bảng đồng hồ kỹ thuật số LCD là một điểm nhấn khác của <b>honda vario 125 nhập</b>. Thiết kế hiện đại này cung cấp đầy đủ thông tin cần thiết như mức tiêu thụ nhiên liệu, tốc độ, thông báo thay dầu và tình trạng pin. Người lái có thể dễ dàng theo dõi các thông số quan trọng trong suốt quá trình di chuyển.</p>\n<p><em>Không gian lưu trữ rộng rãi</em></p>\n<p>Cốp xe với dung tích lên đến 18 lít cho phép người dùng chứa mũ bảo hiểm cùng nhiều vật dụng cá nhân khác một cách thoải mái. Không gian lưu trữ rộng rãi này mang lại sự tiện lợi tối đa cho những chuyến đi xa hoặc hàng ngày.</p>\n<p><em>Công nghệ chìa khóa thông minh Smartkey</em></p>\n<p>Với hệ thống chìa khóa thông minh Smartkey, việc khởi động động cơ và khóa ghi đông trở nên dễ dàng hơn bao giờ hết. Chức năng báo động chống trộm cùng khả năng tìm kiếm xe trong bãi đỗ cũng là những tính năng đáng giá mà công nghệ này mang lại.</p>\n<p><em>Bộ Sạc USB tiện lợi</em></p>\n<p>Cuối cùng, bộ sạc USB tích hợp trong hộp điều khiển giúp người dùng sạc nhanh chóng các thiết bị điện tử với công suất tối đa 5V 2.1A. Đây là một tính năng hữu ích cho những ai thường xuyên sử dụng điện thoại hoặc các thiết bị di động khác khi di chuyển.</p>\n<p>Việc sở hữu <b>vario 125 nhập khẩu</b> không chỉ đáp ứng nhu cầu di chuyển hàng ngày mà còn mang đến trải nghiệm lái xe an toàn, tiện lợi và đầy phong cách. Hãy để chiếc xe này đồng hành cùng bạn trên mọi nẻo đường!</p>\n<h2>3. Giới thiệu động cơ xe Vario 125 nhập khẩu&nbsp;</h2>\n<p><b>Xe vario 125 nhập khẩu</b> nổi bật với động cơ eSP 125 phân khối, mang đến công suất lên tới 11 mã lực và mô-men xoắn đạt 10,8 Nm. Đặc biệt, động cơ này được trang bị công nghệ Idling Stop cùng bộ đề tích hợp ACG, giúp giảm thiểu tiếng ồn trong quá trình khởi động, tạo cảm giác dễ chịu cho người sử dụng.</p>\n<p>Mặc dù sở hữu khối động cơ nhỏ gọn, Honda đã tinh chỉnh các thông số kỹ thuật để <b>Vario 125 nhập</b> hoạt động mạnh mẽ hơn. Xe có khả năng tăng tốc nhanh chóng lên đến 105 km/h mà vẫn duy trì mức tiêu thụ nhiên liệu cực kỳ tiết kiệm chỉ khoảng 1.93L/100km. Điều này không chỉ giúp người lái tiết kiệm chi phí vận hành mà còn góp phần bảo vệ môi trường.</p>\n<p>Với sự kết hợp hoàn hảo giữa sức mạnh và hiệu suất tiết kiệm nhiên liệu, <b>honda vario 125 nhập</b> chắc chắn là lựa chọn hàng đầu cho những tín đồ yêu thích xe ga trong phân khúc này.&nbsp;</p>\n<h2>4. Địa chỉ mua xe Vario 125 nhập khẩu giá tốt</h2>\n<p>Hệ thống xe máy Hùng Phát tự hào là một trong những <a href=\"/xe-may\"><strong>đại lý xe máy</strong></a> hàng đầu chuyên cung cấp xe máy nhập khẩu, đặc biệt là dòng<b> xe vario 125 nhập khẩu</b> với mức giá cạnh tranh. Với nhiều năm kinh nghiệm trong lĩnh vực kinh doanh xe máy, chúng tôi cam kết mang đến cho khách hàng những sản phẩm chất lượng cao cùng dịch vụ tận tâm và chuyên nghiệp.</p>\n<p>Tại Hùng Phát đội ngũ nhân viên giàu kinh nghiệm luôn sẵn sàng lắng nghe và đáp ứng mọi nhu cầu của quý khách. Chúng tôi không chỉ cung cấp các mẫu <a href=\"/xe-may?nhom=xe-may-nhap-khau\"><strong>xe máy nhập khẩu</strong></a> cao cấp mà còn áp dụng nhiều chính sách ưu đãi hấp dẫn nhằm mang lại lợi ích tối đa cho khách hàng.</p>\n<p>Khi đến với cửa hàng của chúng tôi, quý khách sẽ được trải nghiệm không gian mua sắm thân thiện và dịch vụ chăm sóc khách hàng chu đáo. Đừng ngần ngại liên hệ với chúng tôi qua hotline để được tư vấn miễn phí về dòng xe <b>honda vario 125 nhập</b> cũng như chương trình khuyến mãi hiện có.</p>\n<p><strong>HỆ THỐNG XE MÁY HÙNG PHÁT&nbsp;</strong></p>', 1);
