INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-winner-x', 'Xe Winner X', 'honda', '[\"xe-tay-con\"]', 47900000, 54000000, '/sites/hungphat/img/2024/11/winner-x-phien-ban-the-thao-mau-do-den-trang.webp', '[\"/sites/hungphat/img/2024/11/winner-x-phien-ban-the-thao-mau-do-den-trang.webp\"]', '[\"Bạc Đen\",\"Đen\",\"Đen Bạc\",\"Đỏ Đen\",\"Đỏ Đen Trắng\",\"Trắng Đen\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/winner-x-phien-ban-tieu-chuan-mau-do-den.webp\",\"price\":47900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Trắng Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/winner-x-phien-ban-tieu-chuan-mau-trang-den.webp\",\"price\":47900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Bạc\"}],\"img\":\"/sites/hungphat/img/2024/11/winner-x-phien-ban-tieu-chuan-mau-den-bac.webp\",\"price\":47900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/winner-x-phien-ban-dac-biet-mau-do-den.webp\",\"price\":51900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/winner-x-phien-ban-dac-biet-mau-den.webp\",\"price\":51900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Bạc Đen\"}],\"img\":\"/sites/hungphat/img/2024/11/winner-x-phien-ban-dac-biet-mau-bac-den.webp\",\"price\":51900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Đen Trắng\"}],\"img\":\"/sites/hungphat/img/2024/11/winner-x-phien-ban-the-thao-mau-do-den-trang.webp\",\"price\":54000000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Dung tích xy-lanh\",\"value\":\"149,2 cm3\"},{\"label\":\"Tỷ số nén\",\"value\":\"11,3:1\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Loại động cơ\",\"value\":\"PGM-FI, DOHC, 4 kỳ, xy-lanh đơn, côn tay 6 cấp số, làm mát bằng chất lỏng\"},{\"label\":\"Công suất tối đa\",\"value\":\"11,5kW/9.000 vòng/phút\"},{\"label\":\"Đường kính x Hành trình pít tông\",\"value\":\"57,30 mm x 57,84 mm\"},{\"label\":\"Moment cực đại\",\"value\":\"13,5Nm/7.000 vòng/phút\"},{\"label\":\"Mức tiêu thụ nhiên liệu\",\"value\":\"1,98 lít/100km\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Phuộc trước\",\"value\":\"Ống lồng, giảm chấn thủy lực\"},{\"label\":\"Kích cỡ lốp trước/ sau\",\"value\":\"Trước: 90/80-17M/C 46P Sau: 120/70-17M/C 58P\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ đơn\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Khối lượng bản thân\",\"value\":\"122 kg\"},{\"label\":\"Độ cao yên\",\"value\":\"795 mm\"},{\"label\":\"Khoảng sáng gầm xe\",\"value\":\"151 mm\"},{\"label\":\"Khoảng cách trục bánh xe\",\"value\":\"1.278 mm\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"4,5 lít\"},{\"label\":\"Dung tích nhớt máy\",\"value\":\"1,1 lít khi thay nhớt 1,3 lít khi rã máy\"},{\"label\":\"Dài x Rộng x Cao\",\"value\":\"2.019 x 727 x 1.104 mm\"}]}]', '<p>Hướng tới việc trở thành mẫu xe tay côn hàng đầu tại thị trường, xe winner x phiên bản mới tiếp tục thể hiện sự độc đáo và khác biệt với thiết kế mạnh mẽ đầy cuốn hút.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE WINNER X KHUYẾN MÃI CỰC RẺ TẠI ĐẠI LÝ HONDA</h2>\n<p>Hướng tới việc trở thành mẫu xe tay côn hàng đầu tại thị trường, <b>xe winner x </b>phiên bản mới tiếp tục thể hiện sự độc đáo và khác biệt với thiết kế mạnh mẽ đầy cuốn hút. Chiếc xe<b> honda winner x</b> này không chỉ thu hút mọi ánh nhìn mà còn mang lại cảm giác lái đầy phấn khích cho người chủ sở hữu.</p>\n<p>Dưới đây là thiết kế chi tiết của <b>honda winner</b> và <b>giá xe winner x</b> mới nhất hiện nay.</p>\n\n<h2>1. Khám phá thiết kế đột phá và phiên bản màu sắc của dòng xe Winner&nbsp;</h2>\n<p><em>Màu sắc đa dạng và ấn tượng</em></p>\n<p>Dòng <b>xe winner x</b> không chỉ gây ấn tượng bởi hiệu suất vận hành mà còn thu hút ánh nhìn với cách phối màu bắt mắt, <b>winner x</b> mang đến cho người lái một phong cách mạnh mẽ và cá tính. Các phiên bản màu sắc của được thiết kế tinh tế, phù hợp với nhiều đối tượng khách hàng khác nhau.</p>\n\n<p>– Phiên bản Thể thao – Đỏ Đen Trắng: Lấy cảm hứng từ mẫu xe thể thao huyền thoại CBR1000RR-R, <b>winner x</b> phiên bản thể thao gây ấn tượng mạnh mẽ với sự kết hợp hoàn hảo giữa ba tông màu đỏ, đen và trắng. Điểm nhấn đặc biệt của phiên bản này là vành xe màu vàng đồng, tạo nên vẻ ngoài năng động, thể thao đầy cuốn hút.</p>\n<p>– Phiên bản Đặc biệt: Với ba phiên bản màu sắc độc đáo bao gồm Đen Đỏ, Đen Bạc và Đen, <b>xe winner</b> mang đến sự mạnh mẽ và lôi cuốn. Dải tem vàng nổi bật trên thân xe và phần mặt nạ phía trước không chỉ tăng cường tính thẩm mỹ mà còn khẳng định phong cách riêng biệt của người lái.</p>\n<p>– Phiên bản Tiêu chuẩn: Bao gồm ba màu sắc trẻ trung là Đen Bạc, Trắng Đen và Đỏ Đen, <b>honda winner x</b> phiên bản tiêu chuẩn hướng tới những tín đồ yêu thích sự mới mẻ với màu tem được phối hợp một cách sáng tạo, tạo nên nét thể thao tràn đầy sức sống.</p>\n<p><em>Kiểu dáng thể thao ấn tượng</em></p>\n<p><b>Honda winner </b>tiếp tục duy trì phong cách thiết kế mạnh mẽ và nam tính. Những đường nét thiết kế chắc chắn từ đầu đến đuôi xe tạo nên một tổng thể liền mạch, mang lại cảm giác vững chãi cho người điều khiển. Điểm nhấn trong thiết kế là các đường cắt tạo hình chữ V, giúp tăng cường tính khí động học cũng như hình ảnh nhanh nhẹn cho chiếc xe.</p>\n\n<p><em>Mâm xe thiết kế thể thao</em></p>\n<p>Một trong những yếu tố quan trọng góp phần vào trải nghiệm lái tuyệt vời của <b>winner </b>x chính là thiết kế mâm xe. Với trọng lượng nhẹ hơn so với các thế hệ trước, <b>xe winner x</b> mang lại cảm giác lái linh hoạt hơn bao giờ hết. Người điều khiển dễ dàng chuyển hướng mà không gặp khó khăn nào.</p>\n<p>Mâm <b>xe winner</b> mới không chỉ giúp giảm trọng lượng mà còn tạo ra vẻ ngoài thể thao đầy năng động. Thiết kế này không chỉ hướng tới hiệu suất mà còn khẳng định phong cách sống hiện đại của người sử dụng.</p>\n<h2>2. Động cơ và tính năng của Honda Winner X</h2>\n<p><b>Xe winner x</b> tiếp tục khẳng định vị thế của mình trong phân khúc xe thể thao với khối động cơ mạnh mẽ 150cc, trang bị công nghệ DOHC hiện đại. Động cơ này không chỉ mang lại hiệu suất vượt trội mà còn đảm bảo sự ổn định và bền bỉ trong suốt quá trình vận hành.</p>\n\n<p>Một trong những điểm nổi bật của <b>honda winner</b> là bộ ly hợp chống trượt hai chiều mới. Công nghệ này giúp người lái dễ dàng chuyển số mà không lo lắng về tình trạng khóa bánh sau do phanh động cơ khi về số đột ngột. Điều này không chỉ nâng cao tính an toàn mà còn mang đến trải nghiệm lái thú vị hơn trên mọi cung đường, đặc biệt là trong các tình huống cần tăng tốc nhanh hoặc giảm tốc đột ngột.</p>\n<p>Ngoài ra, <b>xe winner x</b> còn được trang bị công nghệ giảm thiểu rung lắc và tiếng ồn vượt trội. Nhờ vào việc sử dụng đối trọng đồng trục và bạc lót để giữ ổ bi, cùng với các giải pháp kỹ thuật như bánh răng nghiêng và vòng bi cho heo số, xe mang lại cảm giác lái mượt mà và thoải mái hơn bao giờ hết. Điều này giúp người lái tận hưởng những chuyến đi dài mà không bị mệt mỏi bởi tiếng ồn hay rung lắc khó chịu.</p>\n<p>Công nghệ PGM-FI kết hợp với các giải pháp giảm thiểu ma sát tối ưu cũng là một điểm nhấn đáng chú ý của <b>winner x</b>. Với thiết kế xi lanh lệch tâm, váy piston có đường vân thô cùng lớp phủ molybdenum, cò mổ con lăn và cấu trúc giảm ma sát ở ống lót xi lanh, xe không chỉ đạt được công suất vượt trội mà còn tiết kiệm nhiên liệu hiệu quả. Điều này giúp người dùng tiết kiệm chi phí vận hành đồng thời bảo vệ môi trường.</p>\n<p><b>Honda winner</b> chính là sự kết hợp hoàn hảo giữa công nghệ tiên tiến và trải nghiệm lái tuyệt vời. Với những tính năng nổi bật như động cơ mạnh mẽ, bộ ly hợp chống trượt hai chiều, công nghệ giảm thiểu rung lắc và tiếng ồn cùng khả năng tiết kiệm nhiên liệu tối ưu, <b>winner</b> chắc chắn sẽ làm hài lòng cả những tay lái khó tính nhất.</p>\n<h2>3. Tiện ích hiện đại của dòng xe Winner X</h2>\n<p>Dòng <b>xe winner x </b>không chỉ nổi bật với thiết kế thể thao, mà còn được trang bị nhiều tiện ích hiện đại, mang đến trải nghiệm lái xe tuyệt vời cho người sử dụng. Dưới đây là những tính năng nổi bật mà <b>honda winner </b>sở hữu.</p>\n<p><em>Mặt đồng hồ kỹ thuật số tinh tế</em></p>\n<p><b>Honda winner x</b> được trang bị mặt đồng hồ kỹ thuật số dạng âm bản hiện đại, với thiết kế nhỏ gọn và hình khối thể thao. Điều này không chỉ giúp người lái dễ dàng quan sát thông tin trong mọi điều kiện ánh sáng mà còn mang lại vẻ đẹp thẩm mỹ cho chiếc xe.</p>\n\n<p><em>Hệ thống khóa thông minh tiện lợi</em></p>\n<p>Tiếp nối thành công từ thế hệ trước, <b>winner</b> vẫn giữ nguyên hệ thống khóa thông minh trên cả ba phiên bản. Tính năng này cho phép người dùng xác định vị trí xe và mở khóa từ xa một cách dễ dàng, mang lại sự tiện lợi tối đa. Đặc biệt, ổ khóa thông minh được trang bị đèn LED xanh khi hoạt động, tạo nên một hình ảnh sang trọng và thời thượng.</p>\n\n<p><em>Cổng sạc USB tiện ích</em></p>\n<p>Phiên bản Đặc biệt và Thể thao của <b>winner x</b> tiếp tục tích hợp cổng sạc USB loại A có nắp chống nước ở phía trước xe. Tính năng này hỗ trợ người lái sạc điện thoại nhanh chóng và thuận tiện khi cần thiết, đáp ứng nhu cầu sử dụng công nghệ hiện đại.</p>\n\n<p><em>Hệ thống phanh ABS an toàn</em></p>\n<p><b>Winner x</b> mang đến cảm giác phấn khích nhưng vẫn đảm bảo sự ổn định và an toàn cho người lái nhờ vào hệ thống chống bó cứng phanh ABS. Hệ thống này được trang bị cho bánh trước trên các phiên bản Đặc biệt và Thể thao, giúp ngăn chặn tình trạng khóa cứng bánh xe khi phanh gấp ở tốc độ cao hoặc di chuyển trên bề mặt trơn trượt.</p>\n\n<p><em>Hệ thống xích xe cải tiến</em></p>\n<p>Hệ thống xích xe của<b> xe winner </b>được nâng cấp với vòng phớt O trên phiên bản Đặc biệt và Thể thao. Cải tiến này không chỉ kéo dài tuổi thọ của xe mà còn tiết kiệm thời gian bảo dưỡng, đồng thời giúp xe vận hành êm ái hơn trong suốt quá trình sử dụng.ư</p>\n\n<h2>4. Giá xe Winner X mới nhất hiện nay tại Hùng Phát&nbsp;</h2>\n<p>Hiện nay, <b>giá xe winner x</b> tiêu chuẩn chỉ từ 47.600.000đ, đây là một trong những mẫu xe tay côn có mức giá hấp dẫn nhất trên thị trường.</p>\n<p>Hùng Phát tự hào là cửa hàng xe máy uy tín hàng đầu hiện nay, với nhiều năm kinh nghiệm trong ngành kinh doanh xe máy. Chúng tôi cam kết mang đến cho quý khách hàng những sản phẩm chất lượng cao cùng dịch vụ tận tâm và chuyên nghiệp nhất. Ngoài dòng xe Honda nổi tiếng, Hùng Phát còn là đại lý chính thức của các thương hiệu lớn như Yamaha, Suzuki, Sym và xe điện Yadea.</p>\n<p>Đừng bỏ lỡ cơ hội sở hữu <b>giá xe winner x</b> ngay hôm nay! Hãy liên hệ với chúng tôi qua hotline để được đội ngũ nhân viên tư vấn miễn phí về các mẫu <a href=\"/xe-may?nhom=honda\"><b>xe honda</b></a> phù hợp với nhu cầu của bạn.</p>\n\n<p>Chúng tôi đang triển khai hàng loạt ưu đãi với mức <a href=\"/xe-may\"><b>giá xe máy</b></a> hấp dẫn dành cho khách hàng:</p>\n<p>– Tặng ngay Combo quà tặng độc quyền trị giá 2.950.000đ</p>\n<p>– Dịch vụ giao xe tận nhà nhanh chóng và tiện lợi</p>\n<p>– Hỗ trợ mua xe trả góp với mức trả trước chỉ từ 10%</p>\n<p>– Bảo hành chính hãng 100% cho mọi sản phẩm</p>\n<p>– Nhiều chương trình khuyến mãi khác đang chờ đón bạn</p>\n<p>Hãy đến với Hùng Phát để tham khảo <b>giá xe winner x</b> mới nhất hiện nay và trải nghiệm dịch vụ chăm sóc khách hàng tốt nhất.</p>\n<p><strong>HỆ THỐNG XE MÁY HÙNG PHÁT&nbsp;</strong></p>', 1);
